function linkWaLead(lead){
  const num=waLead(lead.telefone);
  if(!num)return '';
  const primeiro=(lead.nome||'').trim().split(' ')[0];
  const saud=primeiro?`Olá ${primeiro}!`:'Olá!';
  const msg=encodeURIComponent(`${saud} 😊\n\nVi que você tem interesse em nosso sistema de controle de ponto. Posso te ajudar?\n\n_Guion Informática_`);
  return `https://wa.me/${num}?text=${msg}`;
}

// ╔═ REGRA DE NEGÓCIO ═══════════════════════════════════════════════════════
// Com o Asaas desligado, "Gerar Faturamento Manual" cria uma SOLICITAÇÃO para
// o financeiro. O cliente NÃO vira "Faturado" nesse momento — só quando a
// solicitação for marcada como Resolvida.
// ═══════════════════════════════════════════════════════════════════════════
// Quem recebe a solicitação de faturamento manual.
// Prioridade: responsável marcado em Configurações > primeiro financeiro ativo.
function escolherResponsavelFaturamento(usuarios){
  const lista=(usuarios||[]).filter(u=>u&&u.status!=='revogado');
  return lista.find(u=>u.responsavelFaturamento&&u.email)
    ||lista.find(u=>u.perfil?.toLowerCase()==='financeiro'&&u.email)
    ||lista.find(u=>u.perfil?.toLowerCase()==='financeiro')
    ||null;
}

// --- ENVIO DE WHATSAPP (Datafy) ----------------------------------------------
// Base para as rotinas automáticas: avisar o técnico do agendamento do dia,
// notificar o vendedor de um lead novo, cobrar retorno de orçamento etc.
// A escolha do número é por finalidade; o token fica só no servidor.
async function enviarWhatsApp({para,texto,finalidade,numeroId,template,variaveis,contexto}){
  if(!para)return {ok:false,erro:'Destinatário não informado'};
  try{
    const r=await fetch(`${FUNCTIONS_URL}/datafyEnviar`,{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({para,texto,finalidade,numeroId,template,variaveis,contexto:contexto||''}),
    });
    const d=await r.json();
    if(d.error)return {ok:false,erro:d.error};
    return {ok:true,dados:d};
  }catch(e){
    return {ok:false,erro:e.message};
  }
}
// Envia para um usuário do sistema pelo celular cadastrado
async function avisarUsuario(usuario,texto,contexto){
  if(!usuario?.celular)return {ok:false,erro:`${usuario?.nome||'Usuário'} está sem celular cadastrado`};
  return enviarWhatsApp({para:usuario.celular,texto,finalidade:'interno',contexto});
}

