// ─── Número por extenso (reais) ──────────────────────────────────────────────
const _U=['','um','dois','três','quatro','cinco','seis','sete','oito','nove','dez','onze','doze','treze','quatorze','quinze','dezesseis','dezessete','dezoito','dezenove'];
const _D=['','','vinte','trinta','quarenta','cinquenta','sessenta','setenta','oitenta','noventa'];
const _C=['','cento','duzentos','trezentos','quatrocentos','quinhentos','seiscentos','setecentos','oitocentos','novecentos'];
function _ate999(n){
  if(n===0)return '';
  if(n===100)return 'cem';
  const c=Math.floor(n/100),r=n%100;
  const p=[];
  if(c)p.push(_C[c]);
  if(r){
    if(r<20)p.push(_U[r]);
    else{const d=Math.floor(r/10),u=r%10;p.push(u?`${_D[d]} e ${_U[u]}`:_D[d]);}
  }
  return p.join(' e ');
}
function numeroExtenso(n){
  n=Math.floor(Math.abs(Number(n)||0));
  if(n===0)return 'zero';
  const mi=Math.floor(n/1000000),mil=Math.floor((n%1000000)/1000),res=n%1000;
  const p=[];
  if(mi)p.push(mi===1?'um milhão':`${_ate999(mi)} milhões`);
  if(mil)p.push(mil===1?'mil':`${_ate999(mil)} mil`);
  if(res)p.push(_ate999(res));
  // Em português entra "e" antes do resto quando ele é menor que cem ou uma
  // centena redonda: "dois mil e quinhentos", mas "mil cento e cinquenta".
  const comE=res>0&&(mi||mil)&&(res<100||res%100===0);
  if(comE){
    const ultimo=p.pop();
    return (p.join(' ')+' e '+ultimo).replace(/\s+/g,' ').trim();
  }
  return p.join(' ').replace(/\s+/g,' ').trim();
}
function reaisExtenso(v){
  const n=Number(v)||0;
  const i=Math.floor(n),c=Math.round((n-i)*100);
  const partes=[];
  if(i){
    // Milhão/bilhão exato pede "de reais": "um milhão de reais"
    const de=i>=1000000&&i%1000000===0?'de ':'';
    partes.push(`${numeroExtenso(i)} ${de}${i===1?'real':'reais'}`);
  }
  if(c)partes.push(`${numeroExtenso(c)} ${c===1?'centavo':'centavos'}`);
  if(!partes.length)return 'zero reais';
  return partes.join(' e ');
}
function moedaBR(v){
  return 'R$ '+(Number(v)||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
}
function dataExtenso(d){
  const dt=d?new Date(d):new Date();
  const meses=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
  return `${dt.getDate()} de ${meses[dt.getMonth()]} de ${dt.getFullYear()}`;
}

function useContratoConfig(){
  const [cfg,setCfg]=useState({
    licenciante:LICENCIANTE_PADRAO,objetoPlano:OBJETO_PADRAO,modelo:MODELO_CONTRATO_PADRAO,servicos:[],
  });
  useEffect(()=>{
    const u1=onSnapshot(doc(db,'config','contrato'),d=>{
      if(!d.exists())return;
      const x=d.data();
      setCfg(c=>({
        ...c,
        licenciante:{...LICENCIANTE_PADRAO,...(x.licenciante||{})},
        objetoPlano:{...OBJETO_PADRAO,...(x.objetoPlano||{})},
        modelo:x.modelo||MODELO_CONTRATO_PADRAO,
      }));
    });
    // Os recursos da Cláusula 1 vêm da descrição do serviço vendido, para o
    // contrato dizer exatamente o que foi contratado por aquele cliente.
    const u2=onSnapshot(collection(db,'orc_servicos'),s=>{
      const a=[];s.forEach(d=>a.push({id:d.id,...d.data()}));
      setCfg(c=>({...c,servicos:a}));
    });
    return()=>{u1();u2();};
  },[]);
  return cfg;
}

// Monta o texto final substituindo as variáveis pelos dados do cliente
function montarContrato(cliente,cfg){
  const c=cliente||{};
  const L=cfg.licenciante||LICENCIANTE_PADRAO;
  const plano=c.plano||'Pro';
  const func=parseInt(c.func,10)||0;
  const vS=Number(String(c.vS||0).toString().replace(',','.'))||0;
  const porFunc=func>0?Math.round((vS/func)*100)/100:0;

  const itens=(c.itens||[]).filter(i=>i&&i.nome);
  const listaItens=itens.length
    ? '1.4. Integram este contrato os seguintes itens contratados:\n'+
      itens.map(i=>{
        const qtd=parseInt(i.qtd,10)||1;
        const v=Number(i.valor)||0;
        return `• ${i.nome}${qtd>1?` (${qtd} unidades)`:''}${i.semCusto?' — sem custo':v?` — ${moedaBR(v*qtd)}`:''}`;
      }).join('\n')
    : '';

  // Recursos: descrição do(s) serviço(s) que este cliente contratou.
  // Cada linha da descrição vira um item da lista na Cláusula 1.2.
  const catalogo=cfg.servicos||[];
  const servicosDoCliente=itens.filter(i=>i.tipo==='servico');
  const linhasRecursos=[];
  servicosDoCliente.forEach(i=>{
    const ref=catalogo.find(s=>s.id===i.refId)||catalogo.find(s=>(s.nome||'').toUpperCase()===String(i.nome||'').toUpperCase());
    const desc=String(ref?.descricao||'').trim();
    if(!desc)return;
    desc.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).forEach(linha=>{
      const limpa=linha.replace(/^[•\-*·]\s*/,'').trim();
      if(limpa&&!linhasRecursos.includes(limpa))linhasRecursos.push(limpa);
    });
  });
  const recursos=linhasRecursos.length
    ?linhasRecursos.map(x=>`• ${x}`).join('\n')
    :'• Conforme especificação técnica do plano contratado.';

  const nomeSoftware=({
    Basic:'Gestão Básica de Ponto WEB',
    Pro:'Gestão Profissional (PRO) de Ponto WEB',
    Ultimate:'Gestão Profissional Ultimate de Ponto WEB',
  })[plano]||`Ponto WEB ${plano}`;

  const vars={
    licenciante_razao:L.razaoSocial,licenciante_endereco:L.endereco,licenciante_cnpj:L.cnpj,
    licenciante_representante:L.representante,licenciante_cpf:L.cpf,
    cidade_licenciante:L.cidade,foro:L.foro,
    razao_social:c.nome||c.empresa||'—',
    endereco:c.rua||'—',numero:c.numero||'s/n',complemento:c.complemento||'',
    bairro:c.bairro||'—',cidade:c.cidade||'—',uf:c.uf||'—',cep:c.cep||'—',
    cnpj:c.cnpj||'—',contato:c.contato||'—',email:c.email||'—',telefone:c.tel||'—',
    plano,nome_software:nomeSoftware,
    funcionarios:String(func||'—'),funcionarios_extenso:func?numeroExtenso(func):'—',
    valor_mensal:moedaBR(vS),valor_mensal_extenso:reaisExtenso(vS),
    valor_por_funcionario:moedaBR(porFunc),valor_por_funcionario_extenso:reaisExtenso(porFunc),
    valor_implantacao:moedaBR(c.vI),valor_equipamento:moedaBR(c.vE),
    valor_total:moedaBR(c.total),
    dia_vencimento:c.dtBoleto?String(new Date(c.dtBoleto+'T12:00:00').getDate()):'15',
    data_extenso:dataExtenso(),
    itens_contratados:listaItens,
    recursos,
    objeto:'',
  };
  // O objeto é resolvido antes, porque ele mesmo usa variáveis
  const objetoBruto=(cfg.objetoPlano||OBJETO_PADRAO)[plano]||OBJETO_PADRAO.Pro;
  vars.objeto=objetoBruto.replace(/\{\{\s*(\w+)\s*\}\}/g,(m,k)=>vars[k]??m);

  const texto=(cfg.modelo||MODELO_CONTRATO_PADRAO)
    .replace(/\{\{\s*(\w+)\s*\}\}/g,(m,k)=>vars[k]??'')
    .replace(/\n{3,}/g,'\n\n');

  const semDescricao=servicosDoCliente
    .filter(i=>{
      const ref=catalogo.find(s=>s.id===i.refId)||catalogo.find(s=>(s.nome||'').toUpperCase()===String(i.nome||'').toUpperCase());
      return !String(ref?.descricao||'').trim();
    })
    .map(i=>i.nome);

  const faltando=Object.entries({
    'Razão social':c.nome||c.empresa,CNPJ:c.cnpj,Endereço:c.rua,Número:c.numero,
    Bairro:c.bairro,Cidade:c.cidade,UF:c.uf,CEP:c.cep,'Nº de funcionários':func,
    'Valor mensal':vS,
  }).filter(([,v])=>!v).map(([k])=>k);

  return {texto,vars,faltando,plano,semDescricao};
}

// HTML do documento — mesma base para a prévia, a impressão e o Word
function htmlContrato(texto,cliente,L,id){
  const linhas=texto.split('\n');
  const corpo=linhas.map(l=>{
    const t=l.trim();
    if(!t)return '<p class="vazio">&nbsp;</p>';
    if(/^CONTRATO DE LICENÇA/i.test(t))return `<h1>${t}</h1>`;
    if(/^CLÁUSULA\s/i.test(t))return `<h2>${t}</h2>`;
    if(/^(LICENCIANTE|LICENCIADA):/i.test(t))
      return `<p class="parte">${t.replace(/^(LICENCIANTE|LICENCIADA):/i,'<b>$1:</b>')}</p>`;
    if(/^•/.test(t))return `<p class="item">${t}</p>`;
    return `<p>${t}</p>`;
  }).join('\n');

  return `<!DOCTYPE html>
<html lang="pt-BR"><head><meta charset="utf-8"/>
<title>Contrato — ${(cliente.nome||'cliente').replace(/[<>]/g,'')}</title>
<style>
  @page { size: A4; margin: 22mm 20mm 20mm 20mm; }
  * { box-sizing: border-box; }
  body { font-family: "Times New Roman", Georgia, serif; font-size: 11.5pt; line-height: 1.55;
         color: #111; margin: 0; padding: 0; text-align: justify; }
  .folha { max-width: 170mm; margin: 0 auto; padding: 10mm 0; }
  h1 { font-size: 13pt; text-align: center; text-transform: uppercase; letter-spacing: .5px;
       margin: 0 0 18pt; padding-bottom: 8pt; border-bottom: 2px solid #111; }
  h2 { font-size: 11.5pt; text-transform: uppercase; margin: 16pt 0 6pt; letter-spacing: .3px;
       page-break-after: avoid; }
  p { margin: 0 0 7pt; orphans: 3; widows: 3; }
  p.vazio { margin: 0; height: 4pt; }
  p.parte { margin-bottom: 9pt; }
  p.item { margin: 0 0 3pt 14pt; text-align: left; }
  .assinaturas { margin-top: 26pt; page-break-inside: avoid; }
  .bloco { margin-bottom: 22pt; }
  .bloco .rotulo { font-weight: bold; text-transform: uppercase; font-size: 10.5pt; margin-bottom: 2pt; }
  .bloco .dado { font-size: 10.5pt; line-height: 1.4; }
  .linha { margin-top: 26pt; border-top: 1px solid #111; width: 78mm; padding-top: 3pt;
           font-size: 9.5pt; color: #444; }
  .rodape { margin-top: 22pt; padding-top: 6pt; border-top: 1px solid #ccc;
            font-size: 8pt; color: #777; text-align: center; }
  @media print { .folha { padding: 0; } }
</style></head>
<body><div class="folha">
${corpo}

<div class="assinaturas">
  <div class="bloco">
    <div class="rotulo">Licenciante</div>
    <div class="dado">${L.razaoSocial}<br/>CNPJ: ${L.cnpj}<br/>Representada por: ${L.representante}<br/>CPF: ${L.cpf}</div>
    <div class="linha">Assinatura</div>
  </div>
  <div class="bloco">
    <div class="rotulo">Licenciada</div>
    <div class="dado">${cliente.nome||cliente.empresa||'—'}<br/>CNPJ: ${cliente.cnpj||'—'}${cliente.contato?`<br/>Representada por: ${cliente.contato}`:''}</div>
    <div class="linha">Assinatura</div>
  </div>
</div>

<div class="rodape">Documento ${id} · gerado em ${new Date().toLocaleString('pt-BR')}</div>
</div></body></html>`;
}

// ─── MODAL: PRÉVIA E DOWNLOAD ────────────────────────────────────────────────
function ModalContrato({cliente,onFechar,onRegistrado}){
  const cfg=useContratoConfig();
  const [salvando,setSalvando]=useState(false);
  const [registrado,setRegistrado]=useState(false);

  const {texto,faltando,plano,semDescricao}=useMemo(()=>montarContrato(cliente,cfg),[cliente,cfg]);
  const idDoc=useMemo(()=>'CT-'+new Date().getFullYear()+'-'+String(cliente.id||'').slice(-6).toUpperCase(),[cliente.id]);
  const html=useMemo(()=>htmlContrato(texto,cliente,cfg.licenciante,idDoc),[texto,cliente,cfg,idDoc]);
  const arquivo=`Contrato_${String(cliente.nome||'cliente').replace(/[^\w]+/g,'_').slice(0,40)}`;

  async function registrar(formato){
    if(registrado)return;
    setSalvando(true);
    try{
      await setDoc(doc(db,'contratos',`${cliente.id}_${Date.now()}`),{
        clienteId:cliente.id,clienteNome:cliente.nome||'',cnpj:cliente.cnpj||'',
        plano,documento:idDoc,formato,
        valorMensal:Number(cliente.vS)||0,funcionarios:parseInt(cliente.func,10)||0,
        texto,                                   // congela o texto como foi enviado
        geradoPor:auth.currentUser?.email||'—',
        geradoEm:new Date().toISOString(),
      });
      await setDoc(doc(db,'clientes',cliente.id),{
        contratoGeradoEm:new Date().toISOString(),
        contratoDocumento:idDoc,
      },{merge:true});
      setRegistrado(true);
      onRegistrado&&onRegistrado();
    }catch(e){console.error('[contrato] registro:',e.message);}
    setSalvando(false);
  }

  function baixarPDF(){
    const w=window.open('','_blank','width=900,height=700');
    if(!w){alert('O navegador bloqueou a janela. Libere os pop-ups para este site.');return;}
    w.document.write(html);
    w.document.close();
    w.focus();
    setTimeout(()=>{w.print();},400);
    registrar('pdf');
  }
  function baixarWord(){
    // HTML com cabeçalho do Word: abre no Word já editável, sem dependência
    const doc0='﻿<html xmlns:o="urn:schemas-microsoft-com:office:office" '+
      'xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">'+
      html.replace(/^[\s\S]*?<head>/,'<head>');
    const blob=new Blob([doc0],{type:'application/msword'});
    const a=document.createElement('a');
    a.href=URL.createObjectURL(blob);
    a.download=arquivo+'.doc';
    a.click();
    setTimeout(()=>URL.revokeObjectURL(a.href),2000);
    registrar('word');
  }

  return(
    <div style={{position:'fixed',inset:0,background:'rgba(0,0,0,.65)',zIndex:10000,display:'flex',alignItems:'center',justifyContent:'center',padding:16}}
      onClick={onFechar}>
      <div onClick={e=>e.stopPropagation()}
        style={{background:'#fff',borderRadius:12,width:'100%',maxWidth:860,maxHeight:'92vh',display:'flex',flexDirection:'column',boxShadow:'0 20px 60px rgba(0,0,0,.35)'}}>

        <div style={{padding:'16px 22px',borderBottom:'1px solid #e8eaed',display:'flex',alignItems:'center',gap:12,flexWrap:'wrap'}}>
          <div style={{flex:1,minWidth:200}}>
            <div style={{fontWeight:700,fontSize:15,color:'#2c3e50'}}>Contrato de licença</div>
            <div style={{fontSize:11,color:'#7f8c8d'}}>
              {cliente.nome} · plano {plano} · documento {idDoc}
            </div>
          </div>
          <button onClick={onFechar} style={{background:'none',border:'none',cursor:'pointer',fontSize:20,color:'#95a5a6',lineHeight:1}}>×</button>
        </div>

        {(semDescricao||[]).length>0&&(
          <div style={{margin:'12px 22px 0',background:'#fff8ee',border:'1px solid #fde68a',borderRadius:7,padding:'10px 13px',fontSize:11,color:'#b45309',lineHeight:1.6}}>
            <strong>⚠ Serviço sem descrição:</strong> {semDescricao.join(', ')}.<br/>
            A Cláusula 1.2 lista os recursos a partir da descrição do serviço. Cadastre em
            <strong> Configurações › Orçamento › Serviços</strong>, uma linha por recurso, e o contrato passa a detalhar o que o cliente contratou.
          </div>
        )}

        {faltando.length>0&&(
          <div style={{margin:'12px 22px 0',background:'#fff5f5',border:'1px solid #feb2b2',borderRadius:7,padding:'10px 13px',fontSize:11,color:'#c53030',lineHeight:1.6}}>
            <strong>⚠ Faltam dados no cadastro:</strong> {faltando.join(', ')}.<br/>
            O contrato sai com traço nesses campos. Complete a ficha do cliente antes de enviar.
          </div>
        )}

        <div style={{flex:1,overflowY:'auto',padding:'16px 22px',background:'#f5f6fa'}}>
          <iframe title="Prévia do contrato" srcDoc={html}
            style={{width:'100%',height:520,border:'1px solid #dde1e7',borderRadius:8,background:'#fff'}}/>
        </div>

        <div style={{padding:'14px 22px',borderTop:'1px solid #e8eaed',display:'flex',gap:10,flexWrap:'wrap',alignItems:'center'}}>
          <button onClick={baixarPDF}
            style={{padding:'10px 20px',borderRadius:7,border:'none',background:'#e74c3c',color:'#fff',fontWeight:700,cursor:'pointer',fontSize:13}}>
            📄 Gerar PDF
          </button>
          <button onClick={baixarWord}
            style={{padding:'10px 20px',borderRadius:7,border:'1px solid #2b6cb0',background:'#fff',color:'#2b6cb0',fontWeight:700,cursor:'pointer',fontSize:13}}>
            📝 Baixar Word
          </button>
          <div style={{flex:1}}/>
          {salvando&&<span style={{fontSize:11,color:'#7f8c8d'}}>Registrando...</span>}
          {registrado&&<span style={{fontSize:11,color:'#27ae60',fontWeight:600}}>✓ Registrado no histórico</span>}
        </div>
        <div style={{padding:'0 22px 14px',fontSize:10,color:'#95a5a6',lineHeight:1.6}}>
          No PDF, escolha <strong>Salvar como PDF</strong> na janela de impressão. O arquivo já sai no formato aceito
          por ZapSign, Clicksign e D4Sign — os campos de assinatura ficam no fim, em bloco próprio.
        </div>
      </div>
    </div>
  );
}

// ─── CONFIG: TEXTO DO CONTRATO ───────────────────────────────────────────────
// ─── CONFIG: LIMPEZA DE LEADS ────────────────────────────────────────────────
// Junta duplicados e recolhe contatos que nunca deveriam ter virado lead.
// Sempre mostra a prévia antes: apagar cadastro não tem desfazer.
function ConfigLimpezaLeads(){
  const [plano,setPlano]=useState(null);
  const [analisando,setAnalisando]=useState(false);
  const [executando,setExecutando]=useState(false);
  const [feito,setFeito]=useState(null);
  const [erro,setErro]=useState('');
  const [tirarSemQualif,setTirarSemQualif]=useState(true);
  const [verDetalhe,setVerDetalhe]=useState(false);

  async function chamar(confirmar){
    confirmar?setExecutando(true):setAnalisando(true);
    setErro('');if(confirmar)setFeito(null);
    try{
      const r=await fetch(`${FUNCTIONS_URL}/limparLeads`,{
        method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({confirmar,removerSemQualificacao:tirarSemQualif}),
      });
      const d=await r.json();
      if(d.error)setErro(d.error);
      else if(confirmar){setFeito(d);setPlano(null);}
      else setPlano(d);
    }catch(e){setErro(e.message);}
    setAnalisando(false);setExecutando(false);
  }

  function executar(){
    const n=(plano?.leads_que_serao_removidos_por_duplicidade||0)+(tirarSemQualif?(plano?.contatos_sem_qualificacao||0):0);
    if(!window.confirm(`Confirmar a limpeza?\n\n${n} cadastro(s) serão removidos da lista de leads.\n\nOs dados que só existiam neles são copiados para o cadastro que fica, e uma cópia completa vai para "leads_removidos" — nada é perdido de verdade.`))return;
    chamar(true);
  }

  return(
    <div>
      <div style={{fontWeight:700,fontSize:12,color:'#e67e22',marginBottom:4,textTransform:'uppercase'}}>🧹 Limpeza de leads</div>
      <div style={{fontSize:11,color:'#7f8c8d',marginBottom:12,lineHeight:1.6}}>
        Junta cadastros da mesma pessoa (mesmo telefone) e recolhe os contatos que entraram sem qualificação nenhuma.
        <strong> Sempre mostra o que vai fazer antes de fazer</strong>, e guarda uma cópia do que sair em
        <code style={{fontSize:10,background:'#f8f9fa',padding:'1px 5px',borderRadius:4,margin:'0 3px'}}>leads_removidos</code>.
      </div>

      {erro&&(
        <div style={{background:'#fff5f5',border:'1px solid #feb2b2',borderRadius:7,padding:'10px 13px',marginBottom:12,fontSize:11,color:'#c53030'}}>{erro}</div>
      )}

      {feito&&(
        <div style={{background:'#f0fff4',border:'1px solid #9ae6b4',borderRadius:7,padding:'10px 13px',marginBottom:12,fontSize:11,color:'#276749',lineHeight:1.6}}>
          <strong>✓ Limpeza concluída.</strong> {feito.fundidos} grupo(s) de duplicados unidos, {feito.removidos} cadastro(s) removidos da lista.
        </div>
      )}

      {plano&&(
        <div style={{background:'#fff8ee',border:'1px solid #fde68a',borderRadius:8,padding:'12px 14px',marginBottom:12}}>
          <div style={{fontSize:11,color:'#b45309',lineHeight:1.8,marginBottom:8}}>
            <strong>Prévia — nada foi alterado ainda.</strong><br/>
            {plano.total_de_leads} lead(s) na base.<br/>
            <strong>{plano.grupos_duplicados}</strong> pessoa(s) cadastrada(s) mais de uma vez, resultando em
            {' '}<strong>{plano.leads_que_serao_removidos_por_duplicidade}</strong> cadastro(s) a remover.<br/>
            <strong>{plano.contatos_sem_qualificacao}</strong> contato(s) sem e-mail, sem porte, sem solução, sem dono e sem conversa.
          </div>

          <label style={{display:'flex',alignItems:'flex-start',gap:8,padding:'8px 10px',borderRadius:6,cursor:'pointer',background:'#fff',border:'1px solid #fde68a',marginBottom:8}}>
            <input type="checkbox" checked={tirarSemQualif} onChange={()=>setTirarSemQualif(!tirarSemQualif)} style={{marginTop:2,cursor:'pointer'}}/>
            <div style={{fontSize:11,color:'#4a4a4a',lineHeight:1.5}}>
              Remover também os {plano.contatos_sem_qualificacao} contatos sem qualificação
              <div style={{fontSize:10,color:'#95a5a6',marginTop:2}}>São os que entraram por mensagem de WhatsApp e não têm nenhum dado além do telefone.</div>
            </div>
          </label>

          {(plano.grupos_duplicados>0||plano.contatos_sem_qualificacao>0)&&(
            <button onClick={()=>setVerDetalhe(!verDetalhe)} style={{background:'none',border:'none',cursor:'pointer',color:'#b45309',fontSize:11,fontWeight:700,padding:0,marginBottom:verDetalhe?8:0}}>
              {verDetalhe?'Ocultar detalhes':'Ver o que exatamente vai sair'}
            </button>
          )}

          {verDetalhe&&(
            <div style={{maxHeight:260,overflowY:'auto',background:'#fff',borderRadius:6,padding:'9px 11px',fontSize:10,lineHeight:1.6}}>
              {plano.fusoes.map((f,i)=>(
                <div key={i} style={{marginBottom:7,paddingBottom:7,borderBottom:'1px solid #f5f6fa'}}>
                  <div style={{color:'#276749',fontWeight:700}}>✓ fica: {f.manter.nome||'(sem nome)'} {f.manter.email?`· ${f.manter.email}`:''}</div>
                  {f.remover.map((r,j)=>(
                    <div key={j} style={{color:'#c53030'}}>✕ sai: {r.nome||'(sem nome)'} {r.email?`· ${r.email}`:''}</div>
                  ))}
                </div>
              ))}
              {tirarSemQualif&&plano.semQualificacao.map((s,i)=>(
                <div key={'s'+i} style={{color:'#c53030'}}>✕ sem qualificação: {s.nome||'(sem nome)'} · {s.telefone}</div>
              ))}
            </div>
          )}
        </div>
      )}

      <div style={{display:'flex',alignItems:'center',gap:10,flexWrap:'wrap'}}>
        <button onClick={()=>chamar(false)} disabled={analisando||executando}
          style={{padding:'8px 18px',borderRadius:7,border:'1px solid #e67e22',background:'#fff',color:'#e67e22',fontWeight:700,cursor:'pointer',fontSize:12}}>
          {analisando?'Analisando...':'🔍 Analisar a base'}
        </button>
        {plano&&(plano.grupos_duplicados>0||plano.contatos_sem_qualificacao>0)&&(
          <button onClick={executar} disabled={executando}
            style={{padding:'8px 18px',borderRadius:7,border:'none',background:executando?'#dde1e7':'#e67e22',color:'#fff',fontWeight:700,cursor:'pointer',fontSize:12}}>
            {executando?'Limpando...':'Executar limpeza'}
          </button>
        )}
        {plano&&plano.grupos_duplicados===0&&plano.contatos_sem_qualificacao===0&&(
          <span style={{fontSize:11,color:'#27ae60',fontWeight:600}}>✓ Base limpa, nada a fazer.</span>
        )}
      </div>
    </div>
  );
}

// ─── CONFIG: RAIO-X DO SISTEMA ───────────────────────────────────────────────
// Relatório com leitura de IA, enviado por WhatsApp no horário escolhido.
// Os números são apurados pelo servidor; a IA só interpreta o que recebe.
const SECOES_RAIOX=[
  {id:'leads',       l:'Leads',                 d:'Entradas do dia, sem responsável, parados na etapa, carteira por vendedor, reuniões marcadas.'},
  {id:'comercial',   l:'Comercial',             d:'Clientes novos, faturados do dia e valores, aguardando faturamento, inadimplentes.'},
  {id:'implantacao', l:'Implantação',           d:'Em andamento por etapa, atrasadas, paradas há mais de 7 dias, sem prazo.'},
  {id:'suporte',     l:'Solicitações',          d:'Abertas e concluídas no dia, por prioridade, sem responsável, arrastando há dias.'},
  {id:'automacoes',  l:'Automações',            d:'Mensagens disparadas, falhas de envio, campanhas em andamento, erros no Mailchimp.'},
  {id:'qualidade',   l:'Qualidade do cadastro', d:'Leads sem telefone ou porte, clientes sem CNPJ, usuários sem celular, possíveis duplicados.'},
];

function ConfigRaioX({usuarios}){
  const [c,setC]=useState({
    ativo:false,frequencia:'dias_uteis',horario:'18:00',diaSemana:1,
    destinatarios:[],finalidade:'interno',instrucaoExtra:'',
    secoes:{leads:true,comercial:true,implantacao:true,suporte:true,automacoes:true,qualidade:true},
  });
  const [carregando,setCarregando]=useState(true);
  const [salvando,setSalvando]=useState(false);
  const [salvo,setSalvo]=useState(false);
  const [previa,setPrevia]=useState(null);
  const [gerando,setGerando]=useState(false);
  const [erro,setErro]=useState('');

  const fi={padding:'8px 10px',borderRadius:6,border:'1px solid #dde1e7',fontSize:12,color:'#2c3e50',background:'#fff',width:'100%',boxSizing:'border-box'};
  const lbl={fontSize:10,color:'#7f8c8d',fontWeight:700,textTransform:'uppercase',letterSpacing:.5,display:'block',marginBottom:3};
  const up=(k,v)=>{setC(x=>({...x,[k]:v}));setSalvo(false);};
  const upSecao=(k)=>{const s={...(c.secoes||{})};s[k]=s[k]===false;up('secoes',s);};

  const elegiveis=(usuarios||[]).filter(u=>u.id&&u.status!=='revogado');
  const semCelular=elegiveis.filter(u=>!u.celular);

  useEffect(()=>{
    const unsub=onSnapshot(doc(db,'config','raiox'),d=>{
      if(d.exists())setC(x=>({...x,...d.data(),secoes:{...x.secoes,...(d.data().secoes||{})}}));
      setCarregando(false);
    });
    return()=>unsub();
  },[]);

  async function salvar(){
    setSalvando(true);
    try{
      await setDoc(doc(db,'config','raiox'),{...c,atualizadoEm:new Date().toISOString(),atualizadoPor:auth.currentUser?.email||'—'},{merge:true});
      setSalvo(true);setTimeout(()=>setSalvo(false),2500);
    }catch(e){alert('Erro: '+e.message);}
    setSalvando(false);
  }

  async function gerar(enviar){
    setGerando(true);setPrevia(null);setErro('');
    try{
      const eu=elegiveis.find(u=>u.email===auth.currentUser?.email);
      const r=await fetch(`${FUNCTIONS_URL}/raioXAgora`,{
        method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({apenasGerar:!enviar,paraUsuarioId:enviar?(eu?.id||null):null}),
      });
      const d=await r.json();
      if(d.error)setErro(d.error);
      else setPrevia({texto:d.texto,enviados:d.enviados});
    }catch(e){setErro(e.message);}
    setGerando(false);
  }

  function toggleDest(id){
    const a=c.destinatarios||[];
    up('destinatarios',a.includes(id)?a.filter(x=>x!==id):[...a,id]);
  }

  if(carregando)return <div style={{fontSize:12,color:'#7f8c8d',padding:12}}>Carregando...</div>;

  return(
    <div>
      <div style={{fontWeight:700,fontSize:12,color:'#16a085',marginBottom:4,textTransform:'uppercase'}}>🩻 Raio-x do sistema</div>
      <div style={{fontSize:11,color:'#7f8c8d',marginBottom:12,lineHeight:1.6}}>
        No horário escolhido, o sistema levanta os números do dia, pede uma leitura à IA e manda por WhatsApp
        para quem você marcar. <strong>Os números são apurados pelo servidor</strong> — a IA só interpreta o que recebe,
        então ela não tem como inventar dado.
      </div>

      <div style={{display:'grid',gridTemplateColumns:'1fr 1fr 1fr',gap:10,marginBottom:12}}>
        <div>
          <label style={lbl}>Quando</label>
          <select style={fi} value={c.frequencia} onChange={e=>up('frequencia',e.target.value)}>
            <option value="diario">Todo dia</option>
            <option value="dias_uteis">Dias úteis</option>
            <option value="semanal">Uma vez por semana</option>
          </select>
        </div>
        <div>
          <label style={lbl}>Horário</label>
          <select style={fi} value={c.horario} onChange={e=>up('horario',e.target.value)}>
            {Array.from({length:48},(_,i)=>`${String(Math.floor(i/2)).padStart(2,'0')}:${i%2===0?'00':'30'}`)
              .map(h=><option key={h} value={h}>{h}</option>)}
          </select>
        </div>
        <div>
          {c.frequencia==='semanal'
            ?<>
              <label style={lbl}>Dia da semana</label>
              <select style={fi} value={c.diaSemana} onChange={e=>up('diaSemana',Number(e.target.value))}>
                {['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'].map((d,i)=><option key={i} value={i}>{d}</option>)}
              </select>
            </>
            :<>
              <label style={lbl}>Enviar pelo número</label>
              <select style={fi} value={c.finalidade} onChange={e=>up('finalidade',e.target.value)}>
                {FINALIDADES_WA.map(f=><option key={f.id} value={f.id}>{f.label}</option>)}
              </select>
            </>}
        </div>
      </div>

      <div style={{marginBottom:12}}>
        <label style={lbl}>Quem recebe</label>
        <div style={{display:'flex',gap:6,flexWrap:'wrap'}}>
          {elegiveis.map(u=>{
            const sel=(c.destinatarios||[]).includes(u.id);
            const sem=!u.celular;
            return(
              <button key={u.id} onClick={()=>toggleDest(u.id)} disabled={sem}
                title={sem?'Sem celular cadastrado em Usuários e acessos':''}
                style={{padding:'5px 13px',borderRadius:16,cursor:sem?'not-allowed':'pointer',fontSize:11,fontWeight:700,
                  border:`1px solid ${sel?'#16a085':'#dde1e7'}`,
                  background:sel?'#16a085':'#fff',color:sel?'#fff':sem?'#c0c0c0':'#7f8c8d',opacity:sem?.6:1}}>
                {u.nome||u.email}{sem?' ⚠':''}
              </button>
            );
          })}
        </div>
        {semCelular.length>0&&(
          <div style={{fontSize:10,color:'#c0392b',marginTop:5}}>
            ⚠ Sem celular cadastrado: {semCelular.map(u=>u.nome||u.email).join(', ')}
          </div>
        )}
      </div>

      <div style={{marginBottom:12}}>
        <label style={lbl}>O que entra no relatório</label>
        <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:6}}>
          {SECOES_RAIOX.map(s=>{
            const on=(c.secoes||{})[s.id]!==false;
            return(
              <label key={s.id} style={{display:'flex',alignItems:'flex-start',gap:8,padding:'8px 10px',borderRadius:7,cursor:'pointer',
                background:on?'#f0fffd':'#f8f9fa',border:`1px solid ${on?'#a7f3e4':'#e8eaed'}`}}>
                <input type="checkbox" checked={on} onChange={()=>upSecao(s.id)} style={{marginTop:2,cursor:'pointer',flexShrink:0}}/>
                <div>
                  <div style={{fontWeight:700,fontSize:11,color:'#2c3e50'}}>{s.l}</div>
                  <div style={{fontSize:10,color:'#95a5a6',lineHeight:1.5,marginTop:1}}>{s.d}</div>
                </div>
              </label>
            );
          })}
        </div>
      </div>

      <div style={{marginBottom:12}}>
        <label style={lbl}>O que a IA deve olhar com atenção (opcional)</label>
        <textarea style={{...fi,minHeight:60,resize:'vertical',lineHeight:1.6}} value={c.instrucaoExtra}
          onChange={e=>up('instrucaoExtra',e.target.value)}
          placeholder="Ex: cobrar quando lead do Meta Ads ficar mais de 1 dia sem responsável. Avisar sempre que houver implantação atrasada. Comentar a performance de cada vendedor."/>
      </div>

      <label style={{display:'flex',alignItems:'flex-start',gap:9,padding:'11px 13px',borderRadius:8,cursor:'pointer',marginBottom:12,
        background:c.ativo?'#f0fffd':'#f8f9fa',border:`1px solid ${c.ativo?'#a7f3e4':'#e8eaed'}`}}>
        <input type="checkbox" checked={!!c.ativo} onChange={()=>up('ativo',!c.ativo)} style={{marginTop:2,cursor:'pointer',flexShrink:0}}/>
        <div>
          <div style={{fontWeight:700,fontSize:12,color:'#2c3e50'}}>Enviar automaticamente</div>
          <div style={{fontSize:10,color:'#95a5a6',lineHeight:1.6,marginTop:2}}>
            Dispara uma vez por dia, na janela de uma hora após o horário escolhido. Se o sistema estiver fora do ar
            nesse intervalo, ele não manda atrasado no dia seguinte.
          </div>
        </div>
      </label>

      {erro&&(
        <div style={{background:'#fff5f5',border:'1px solid #feb2b2',borderRadius:7,padding:'10px 13px',marginBottom:12,fontSize:11,color:'#c53030'}}>
          {erro}
        </div>
      )}

      {previa&&(
        <div style={{background:'#f8f9fa',border:'1px solid #e8eaed',borderRadius:8,padding:'12px 14px',marginBottom:12}}>
          <div style={{fontSize:10,color:'#16a085',fontWeight:700,textTransform:'uppercase',letterSpacing:.5,marginBottom:7}}>
            Como vai chegar no WhatsApp{previa.enviados?` · enviado para ${previa.enviados}`:''}
          </div>
          <div style={{background:'#dcf8c6',borderRadius:8,padding:'11px 13px',fontSize:12,color:'#2c3e50',lineHeight:1.7,whiteSpace:'pre-wrap',maxWidth:460}}>
            {previa.texto}
          </div>
        </div>
      )}

      <div style={{display:'flex',alignItems:'center',gap:10,flexWrap:'wrap'}}>
        <button onClick={salvar} disabled={salvando}
          style={{padding:'8px 20px',borderRadius:7,border:'none',background:salvo?'#27ae60':'#16a085',color:'#fff',fontWeight:700,cursor:'pointer',fontSize:12}}>
          {salvando?'Salvando...':salvo?'✓ Salvo!':'Salvar'}
        </button>
        <button onClick={()=>gerar(false)} disabled={gerando}
          style={{padding:'8px 16px',borderRadius:7,border:'1px solid #16a085',background:'#fff',color:'#16a085',cursor:'pointer',fontSize:12,fontWeight:700}}>
          {gerando?'Analisando...':'👁 Ver como fica agora'}
        </button>
        <button onClick={()=>gerar(true)} disabled={gerando}
          style={{padding:'8px 16px',borderRadius:7,border:'1px solid #dde1e7',background:'#fff',color:'#7f8c8d',cursor:'pointer',fontSize:12,fontWeight:600}}>
          Mandar no meu WhatsApp
        </button>
      </div>
    </div>
  );
}

// ─── CONFIG: MAILCHIMP ───────────────────────────────────────────────────────
// A régua de dias mora no Customer Journey do Mailchimp. Aqui só ligamos a
// conta, escolhemos a audiência e a tag que dispara a jornada.
function ConfigMailchimp(){
  const [c,setC]=useState({apiKey:'',audienceId:'',tag:'sequencia-oferta',ativo:false,status:'subscribed',aoConverter:'arquivar'});
  const [carregando,setCarregando]=useState(true);
  const [salvando,setSalvando]=useState(false);
  const [salvo,setSalvo]=useState(false);
  const [testando,setTestando]=useState(false);
  const [audiencias,setAudiencias]=useState([]);
  const [resultado,setResultado]=useState(null);
  const [sincronizando,setSincronizando]=useState(false);
  const [verGuia,setVerGuia]=useState(false);

  const fi={padding:'8px 10px',borderRadius:6,border:'1px solid #dde1e7',fontSize:12,color:'#2c3e50',background:'#fff',width:'100%',boxSizing:'border-box'};
  const lbl={fontSize:10,color:'#7f8c8d',fontWeight:700,textTransform:'uppercase',letterSpacing:.5,display:'block',marginBottom:3};
  const up=(k,v)=>{setC(x=>({...x,[k]:v}));setSalvo(false);};

  useEffect(()=>{
    const unsub=onSnapshot(doc(db,'config','mailchimp'),d=>{
      if(d.exists())setC(x=>({...x,...d.data()}));
      setCarregando(false);
    });
    return()=>unsub();
  },[]);

  async function salvar(){
    setSalvando(true);
    try{
      await setDoc(doc(db,'config','mailchimp'),{...c,atualizadoEm:new Date().toISOString(),atualizadoPor:auth.currentUser?.email||'—'},{merge:true});
      setSalvo(true);setTimeout(()=>setSalvo(false),2500);
    }catch(e){alert('Erro: '+e.message);}
    setSalvando(false);
  }

  async function testar(){
    if(!c.apiKey.trim()){alert('Cole a chave da API primeiro.');return;}
    setTestando(true);setResultado(null);
    try{
      const r=await fetch(`${FUNCTIONS_URL}/mailchimpProxy`,{
        method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({acao:'testar',apiKey:c.apiKey.trim()}),
      });
      const d=await r.json();
      if(d.error)setResultado({erro:d.error});
      else{setAudiencias(d.audiencias||[]);setResultado({ok:true,total:(d.audiencias||[]).length});}
    }catch(e){setResultado({erro:e.message});}
    setTestando(false);
  }

  async function sincronizarTudo(){
    if(!c.audienceId){alert('Escolha a audiência antes.');return;}
    if(!window.confirm('Enviar todos os leads com e-mail para a audiência do Mailchimp?\n\nQuem já está lá é apenas atualizado, não duplica. Atenção: quem receber a tag entra na jornada.'))return;
    setSincronizando(true);setResultado(null);
    try{
      const r=await fetch(`${FUNCTIONS_URL}/mailchimpProxy`,{
        method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({acao:'sincronizar'}),
      });
      const d=await r.json();
      if(d.error)setResultado({erro:d.error});
      else setResultado({sync:d});
    }catch(e){setResultado({erro:e.message});}
    setSincronizando(false);
  }

  if(carregando)return <div style={{fontSize:12,color:'#7f8c8d',padding:12}}>Carregando...</div>;

  const listaAud=audiencias.length?audiencias:(c.audienceId?[{id:c.audienceId,nome:'(audiência salva)',membros:'—'}]:[]);

  return(
    <div>
      <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:4,flexWrap:'wrap'}}>
        <div style={{fontWeight:700,fontSize:12,color:'#f5a623',textTransform:'uppercase'}}>✉️ Mailchimp — régua de e-mails</div>
        <div style={{flex:1}}/>
        <button onClick={()=>setVerGuia(!verGuia)} style={{background:'none',border:'none',cursor:'pointer',color:'#3498db',fontSize:11,fontWeight:700}}>
          {verGuia?'Ocultar':'Como configurar'}
        </button>
      </div>
      <div style={{fontSize:11,color:'#7f8c8d',marginBottom:12,lineHeight:1.6}}>
        Todo lead com e-mail entra na audiência com a tag abaixo. <strong>A espera de 3, 5 e 7 dias é montada no
        Customer Journey do Mailchimp</strong> — assim você muda texto, arte e prazo lá, sem mexer no sistema.
      </div>

      {verGuia&&(
        <div style={{background:'#ebf8ff',border:'1px solid #bee3f8',borderRadius:8,padding:'12px 15px',marginBottom:12,fontSize:11,color:'#2b6cb0',lineHeight:1.8}}>
          <strong>1. Chave da API.</strong> No Mailchimp, clique na sua foto no canto superior direito e escolha
          <strong>Perfil</strong>. Abra o menu <strong>Extras › Chaves de API</strong> e clique em <strong>Criar uma chave</strong>.
          Copie e cole aqui embaixo — o final dela (ex: <code>-us21</code>) é o servidor, o sistema identifica sozinho.<br/>
          <strong>2. Audiência.</strong> Clique em <strong>Testar conexão</strong> aqui embaixo: as suas audiências aparecem
          na lista, é só escolher. Você não precisa procurar o número dela no Mailchimp.<br/>
          <strong>3. Etiqueta.</strong> No menu lateral do Mailchimp, vá em <strong>Público › Etiquetas</strong> e crie a
          etiqueta <code>{c.tag||'sequencia-oferta'}</code>, escrita exatamente igual. Ela precisa existir antes, senão
          a jornada não deixa você escolhê-la.<br/>
          <strong>4. Jornada.</strong> Vá em <strong>Automações</strong>, comece um fluxo do zero, dê um nome e escolha
          a audiência. Em acionador, escolha <strong>"Etiqueta adicionada"</strong> e informe a mesma etiqueta.<br/>
          <strong>5. Montagem.</strong> <em>e-mail de oferta</em> → <strong>Atraso de 3 dias</strong> → <em>e-mail 2</em> →
          <strong> Atraso de 2 dias</strong> (cai no 5º) → <em>e-mail 3</em> → <strong>Atraso de 2 dias</strong> (cai no 7º) →
          <em>e-mail final</em>. O atraso conta a partir do passo anterior, não da entrada — por isso 3, 2 e 2, não 3, 5 e 7.<br/>
          <strong>6.</strong> Clique em <strong>Continuar</strong> e depois em <strong>Ativar fluxo</strong>. Só então ligue
          a chave aqui embaixo.
        </div>
      )}

      <div style={{display:'grid',gridTemplateColumns:'2fr 1fr',gap:10,marginBottom:10}}>
        <div>
          <label style={lbl}>Chave da API</label>
          <input style={fi} type="password" value={c.apiKey} onChange={e=>up('apiKey',e.target.value)}
            placeholder="a1b2c3d4e5f6...-us21" autoComplete="off"/>
        </div>
        <div style={{display:'flex',alignItems:'flex-end'}}>
          <button onClick={testar} disabled={testando}
            style={{padding:'8px 16px',borderRadius:6,border:'1px solid #f5a623',background:'#fff',color:'#b45309',fontWeight:700,cursor:'pointer',fontSize:12,width:'100%'}}>
            {testando?'Testando...':'Testar conexão'}
          </button>
        </div>
      </div>

      <div style={{display:'grid',gridTemplateColumns:'2fr 1fr',gap:10,marginBottom:10}}>
        <div>
          <label style={lbl}>Audiência</label>
          <select style={fi} value={c.audienceId} onChange={e=>up('audienceId',e.target.value)}>
            <option value="">— Teste a conexão para listar —</option>
            {listaAud.map(a=><option key={a.id} value={a.id}>{a.nome} ({a.membros} contatos)</option>)}
          </select>
        </div>
        <div>
          <label style={lbl}>Tag que dispara a jornada</label>
          <input style={fi} value={c.tag} onChange={e=>up('tag',e.target.value)} placeholder="sequencia-oferta"/>
        </div>
      </div>

      <div style={{marginBottom:10}}>
        <label style={lbl}>Como inscrever</label>
        <select style={{...fi,maxWidth:340}} value={c.status} onChange={e=>up('status',e.target.value)}>
          <option value="subscribed">Direto (lead do anúncio já autorizou o contato)</option>
          <option value="pending">Com confirmação por e-mail (dupla verificação)</option>
        </select>
        <div style={{fontSize:10,color:'#95a5a6',marginTop:3,lineHeight:1.5}}>
          Com confirmação, a jornada só começa depois que a pessoa clicar no e-mail de confirmação — chega em menos gente,
          mas protege mais a reputação do seu domínio.
        </div>
      </div>

      <div style={{marginBottom:10}}>
        <label style={lbl}>Quando o lead vira cliente (ou é perdido)</label>
        <select style={{...fi,maxWidth:420}} value={c.aoConverter||'arquivar'} onChange={e=>up('aoConverter',e.target.value)}>
          <option value="arquivar">Arquivar no Mailchimp — para de receber tudo</option>
          <option value="tags">Só trocar as etiquetas — sai da jornada, continua na base</option>
          <option value="nada">Não fazer nada</option>
        </select>
        <div style={{fontSize:10,color:'#95a5a6',marginTop:4,lineHeight:1.6}}>
          Arquivar é reversível e é o único jeito de garantir que a jornada pare no meio.
          <strong> O sistema nunca exclui em definitivo</strong> — e-mail excluído assim no Mailchimp não pode mais ser
          recadastrado, nunca. Se escolher só trocar etiquetas, acrescente na sua jornada uma regra de saída
          para quem tiver a etiqueta <code style={{fontSize:10}}>cliente</code>.
        </div>
      </div>

      <label style={{display:'flex',alignItems:'flex-start',gap:9,padding:'11px 13px',borderRadius:8,cursor:'pointer',marginBottom:12,
        background:c.ativo?'#f0fff4':'#f8f9fa',border:`1px solid ${c.ativo?'#9ae6b4':'#e8eaed'}`}}>
        <input type="checkbox" checked={!!c.ativo} onChange={()=>up('ativo',!c.ativo)} style={{marginTop:2,cursor:'pointer',flexShrink:0}}/>
        <div>
          <div style={{fontWeight:700,fontSize:12,color:'#2c3e50'}}>Enviar leads automaticamente</div>
          <div style={{fontSize:10,color:'#95a5a6',lineHeight:1.6,marginTop:2}}>
            Todo lead novo com e-mail válido entra na audiência na hora. Quem chega sem e-mail e recebe um depois
            (o contato do WhatsApp que preenche o formulário) também entra.
          </div>
        </div>
      </label>

      {resultado&&(
        <div style={{borderRadius:7,padding:'10px 13px',marginBottom:12,fontSize:11,lineHeight:1.6,
          background:resultado.erro?'#fff5f5':'#f0fff4',border:`1px solid ${resultado.erro?'#feb2b2':'#9ae6b4'}`,
          color:resultado.erro?'#c53030':'#276749'}}>
          {resultado.erro&&<><strong>Falhou:</strong> {resultado.erro}</>}
          {resultado.ok&&<><strong>✓ Conectado.</strong> {resultado.total} audiência(s) encontrada(s). Escolha a sua acima e salve.</>}
          {resultado.sync&&(
            <>
              <strong>✓ Sincronização concluída.</strong> {resultado.sync.enviados} enviado(s), {resultado.sync.pulados} sem e-mail,
              {' '}{resultado.sync.falhas} falha(s).
              {(resultado.sync.erros||[]).length>0&&(
                <div style={{marginTop:5,color:'#c53030'}}>{resultado.sync.erros.map((e,i)=><div key={i}>• {e}</div>)}</div>
              )}
            </>
          )}
        </div>
      )}

      <div style={{display:'flex',alignItems:'center',gap:10,flexWrap:'wrap'}}>
        <button onClick={salvar} disabled={salvando}
          style={{padding:'8px 20px',borderRadius:7,border:'none',background:salvo?'#27ae60':'#f5a623',color:'#fff',fontWeight:700,cursor:'pointer',fontSize:12}}>
          {salvando?'Salvando...':salvo?'✓ Salvo!':'Salvar'}
        </button>
        <button onClick={sincronizarTudo} disabled={sincronizando||!c.audienceId}
          style={{padding:'8px 16px',borderRadius:7,border:'1px solid #dde1e7',background:'#fff',cursor:c.audienceId?'pointer':'default',fontSize:12,color:'#7f8c8d',fontWeight:600,opacity:c.audienceId?1:.5}}>
          {sincronizando?'Enviando...':'Enviar leads que já existem'}
        </button>
        <span style={{fontSize:10,color:'#95a5a6'}}>
          Salve antes de sincronizar. A sincronização usa a audiência e a tag já gravadas.
        </span>
      </div>
    </div>
  );
}

function ConfigContrato(){
  const [c,setC]=useState({licenciante:LICENCIANTE_PADRAO,objetoPlano:OBJETO_PADRAO,modelo:MODELO_CONTRATO_PADRAO});
  const [carregando,setCarregando]=useState(true);
  const [salvando,setSalvando]=useState(false);
  const [salvo,setSalvo]=useState(false);
  const [aba,setAba]=useState('modelo');
  const [planoSel,setPlanoSel]=useState('Pro');

  const fi={padding:'8px 10px',borderRadius:6,border:'1px solid #dde1e7',fontSize:12,color:'#2c3e50',background:'#fff',width:'100%',boxSizing:'border-box'};
  const lbl={fontSize:10,color:'#7f8c8d',fontWeight:700,textTransform:'uppercase',letterSpacing:.5,display:'block',marginBottom:3};

  useEffect(()=>{
    const unsub=onSnapshot(doc(db,'config','contrato'),d=>{
      if(d.exists()){
        const x=d.data();
        setC({
          licenciante:{...LICENCIANTE_PADRAO,...(x.licenciante||{})},
          objetoPlano:{...OBJETO_PADRAO,...(x.objetoPlano||{})},
          modelo:x.modelo||MODELO_CONTRATO_PADRAO,
        });
      }
      setCarregando(false);
    });
    return()=>unsub();
  },[]);

  async function salvar(){
    setSalvando(true);
    try{
      await setDoc(doc(db,'config','contrato'),{...c,atualizadoEm:new Date().toISOString(),atualizadoPor:auth.currentUser?.email||'—'},{merge:true});
      setSalvo(true);setTimeout(()=>setSalvo(false),2500);
    }catch(e){alert('Erro: '+e.message);}
    setSalvando(false);
  }
  function restaurar(){
    if(!window.confirm('Voltar ao texto padrão? O que você editou será perdido.'))return;
    setC({licenciante:LICENCIANTE_PADRAO,objetoPlano:OBJETO_PADRAO,modelo:MODELO_CONTRATO_PADRAO});
  }

  if(carregando)return <div style={{fontSize:12,color:'#7f8c8d',padding:12}}>Carregando...</div>;

  const VARS=[
    ['razao_social','Razão social do cliente'],['cnpj','CNPJ'],['endereco','Rua'],['numero','Número'],
    ['bairro','Bairro'],['cidade','Cidade'],['uf','UF'],['cep','CEP'],['contato','Contato'],
    ['funcionarios','Nº de funcionários'],['funcionarios_extenso','Nº por extenso'],
    ['plano','Plano'],['nome_software','Nome do software'],
    ['valor_mensal','Valor mensal'],['valor_mensal_extenso','Valor mensal por extenso'],
    ['valor_por_funcionario','Valor por funcionário'],['valor_por_funcionario_extenso','Por extenso'],
    ['valor_implantacao','Implantação'],['valor_equipamento','Equipamento'],['valor_total','Total'],
    ['dia_vencimento','Dia do vencimento'],['data_extenso','Data por extenso'],
    ['objeto','Cláusula 1 do plano'],['recursos','Recursos (descrição do serviço)'],['itens_contratados','Itens contratados'],
    ['licenciante_razao','Razão social da Guion'],['licenciante_cnpj','CNPJ da Guion'],
    ['licenciante_representante','Representante'],['licenciante_cpf','CPF'],
    ['cidade_licenciante','Cidade da Guion'],['foro','Foro'],
  ];

  return(
    <div>
      <div style={{fontWeight:700,fontSize:12,color:'#8e44ad',marginBottom:4,textTransform:'uppercase'}}>📄 Texto do contrato</div>
      <div style={{fontSize:11,color:'#7f8c8d',marginBottom:12,lineHeight:1.6}}>
        O contrato gerado na ficha do cliente usa este texto. Edite aqui e a mudança vale no próximo contrato,
        sem precisar de deploy. Os contratos já emitidos guardam o texto da época e não mudam.
      </div>

      <div style={{display:'flex',gap:6,marginBottom:12,flexWrap:'wrap'}}>
        {[{id:'modelo',l:'Corpo do contrato'},{id:'objeto',l:'Cláusula 1 por plano'},{id:'empresa',l:'Dados da Guion'}].map(a=>(
          <button key={a.id} onClick={()=>setAba(a.id)}
            style={{padding:'7px 15px',borderRadius:7,border:'none',background:aba===a.id?'#8e44ad':'#ecf0f1',color:aba===a.id?'#fff':'#7f8c8d',cursor:'pointer',fontSize:12,fontWeight:aba===a.id?700:400}}>
            {a.l}
          </button>
        ))}
      </div>

      {aba==='modelo'&&(
        <div>
          <textarea value={c.modelo} onChange={e=>{setC(x=>({...x,modelo:e.target.value}));setSalvo(false);}}
            style={{...fi,minHeight:420,resize:'vertical',fontFamily:'ui-monospace,Menlo,Consolas,monospace',fontSize:11,lineHeight:1.7}}/>
          <div style={{marginTop:8,background:'#faf5ff',border:'1px solid #e9d5ff',borderRadius:7,padding:'10px 12px'}}>
            <div style={{fontSize:10,color:'#6b21a8',fontWeight:700,textTransform:'uppercase',marginBottom:6}}>Variáveis disponíveis</div>
            <div style={{display:'flex',gap:4,flexWrap:'wrap'}}>
              {VARS.map(([v,d])=>(
                <span key={v} title={d}
                  style={{background:'#fff',border:'1px solid #e9d5ff',borderRadius:10,padding:'2px 8px',fontSize:10,color:'#6b21a8',fontFamily:'monospace'}}>
                  {'{{'+v+'}}'}
                </span>
              ))}
            </div>
          </div>
        </div>
      )}

      {aba==='objeto'&&(
        <div>
          <div style={{display:'flex',gap:6,marginBottom:8,flexWrap:'wrap'}}>
            {Object.keys(c.objetoPlano).map(p=>(
              <button key={p} onClick={()=>setPlanoSel(p)}
                style={{padding:'5px 14px',borderRadius:6,border:`1px solid ${planoSel===p?'#8e44ad':'#dde1e7'}`,background:planoSel===p?'#faf5ff':'#fff',color:planoSel===p?'#6b21a8':'#7f8c8d',cursor:'pointer',fontSize:11,fontWeight:700}}>
                {p}
              </button>
            ))}
          </div>
          <div style={{fontSize:10,color:'#95a5a6',marginBottom:6}}>
            Este texto entra no lugar de <code>{'{{objeto}}'}</code> quando o cliente tem o plano {planoSel}.
          </div>
          <textarea value={c.objetoPlano[planoSel]||''}
            onChange={e=>{const v=e.target.value;setC(x=>({...x,objetoPlano:{...x.objetoPlano,[planoSel]:v}}));setSalvo(false);}}
            style={{...fi,minHeight:220,resize:'vertical',fontFamily:'ui-monospace,Menlo,Consolas,monospace',fontSize:11,lineHeight:1.7}}/>
        </div>
      )}

      {aba==='empresa'&&(
        <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:10}}>
          {[['razaoSocial','Razão social'],['cnpj','CNPJ'],['endereco','Endereço completo'],
            ['representante','Representante legal'],['cpf','CPF do representante'],
            ['cidade','Cidade da assinatura'],['foro','Comarca do foro']].map(([k,l])=>(
            <div key={k} style={k==='endereco'?{gridColumn:'1 / -1'}:{}}>
              <label style={lbl}>{l}</label>
              <input style={fi} value={c.licenciante[k]||''}
                onChange={e=>{const v=e.target.value;setC(x=>({...x,licenciante:{...x.licenciante,[k]:v}}));setSalvo(false);}}/>
            </div>
          ))}
        </div>
      )}

      <div style={{display:'flex',alignItems:'center',gap:10,marginTop:14,flexWrap:'wrap'}}>
        <button onClick={salvar} disabled={salvando}
          style={{padding:'8px 20px',borderRadius:7,border:'none',background:salvo?'#27ae60':'#8e44ad',color:'#fff',fontWeight:700,cursor:'pointer',fontSize:12}}>
          {salvando?'Salvando...':salvo?'✓ Salvo!':'Salvar texto do contrato'}
        </button>
        <button onClick={restaurar}
          style={{padding:'8px 14px',borderRadius:7,border:'1px solid #dde1e7',background:'#fff',cursor:'pointer',fontSize:12,color:'#7f8c8d'}}>
          Restaurar padrão
        </button>
      </div>
    </div>
  );
}

function PainelSecullum({cliente,perfil,onUpdate}){
  const [aberto,setAberto]=useState(false);
  const [dados,setDados]=useState(null);
  const [carregando,setCarregando]=useState(false);
  const [erro,setErro]=useState('');
  const [codigo,setCodigo]=useState(cliente.codigoBancoSecullum||'');
  const [salvandoCod,setSalvandoCod]=useState(false);
  const [acaoSel,setAcaoSel]=useState(null);
  const [justificativa,setJustificativa]=useState('');
  const [modelo16,setModelo16]=useState('plano');
  const [executando,setExecutando]=useState(false);

  const ehAdmin=perfil==='admin';
  const fi={padding:'8px 10px',borderRadius:6,border:'1px solid #dde1e7',fontSize:13,color:'#2c3e50',background:'#fff',width:'100%',boxSizing:'border-box'};
  const lbl={fontSize:10,color:'#7f8c8d',fontWeight:700,textTransform:'uppercase',letterSpacing:.5,display:'block',marginBottom:3};

  const sync=cliente.secullum_sync;

  async function consultar(){
    if(!codigo){setErro('Informe o código do banco na Secullum.');return;}
    setCarregando(true);setErro('');
    try{
      const r=await fetch(`${FUNCTIONS_URL}/secullumConsultar`,{
        method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({codigo}),
      });
      const d=await r.json();
      if(d.error){setErro(d.error);setDados(null);}
      else{
        setDados(d.dados);
        // Guarda o retorno no cliente para consulta offline
        const s={
          razaoSocial:d.dados.RazaoSocial||d.dados.Nome||'',
          documento:d.dados.Documento||'',
          quantidadePessoas:d.dados.QuantidadePessoas??null,
          limitePessoas:d.dados.LimitePessoas??null,
          limiteEquipamentos:d.dados.LimiteEquipamentos??null,
          plano:d.dados.Plano||'',periodoMeses:d.dados.Periodo_meses??null,
          ativadoEm:d.dados.Ativado_em||'',validade:d.dados.Validade||null,
          dataExclusao:d.dados.DataExclusao||null,
          vencimentoContrato:d.dados.vencimentoContrato||'',
          gestaoArquivos:d.dados.RA_GestaoArquivos||'',ferias:d.dados.RA_Ferias||'',
          software:d.dados.Software||'',atualizadoEm:new Date().toISOString(),
        };
        try{await setDoc(doc(db,'clientes',cliente.id),{secullum_sync:s},{merge:true});}catch(e){}
      }
    }catch(e){setErro('Erro na consulta: '+e.message);}
    setCarregando(false);
  }

  async function salvarCodigo(){
    setSalvandoCod(true);
    try{
      await setDoc(doc(db,'clientes',cliente.id),{codigoBancoSecullum:String(codigo).trim()},{merge:true});
      await registrarHistorico(cliente.id,cliente.nome,'secullum_codigo',`Código do banco Secullum definido: ${codigo}`);
    }catch(e){setErro('Erro ao salvar: '+e.message);}
    setSalvandoCod(false);
  }

  async function executar(){
    const acao=ACOES_SECULLUM.find(a=>a.tipo===acaoSel);
    if(!acao)return;
    if(!justificativa.trim()){setErro('A justificativa é obrigatória.');return;}
    if(!window.confirm(`${acao.icone} ${acao.label}\n\n${acao.confirma}\n\nCliente: ${cliente.nome}\nBanco: ${codigo}\n\nConfirmar?`))return;
    setExecutando(true);setErro('');
    try{
      const r=await fetch(`${FUNCTIONS_URL}/secullumAcao`,{
        method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({
          codigo,tipoSolicitacao:acaoSel,justificativa:justificativa.trim(),
          clienteId:cliente.id,clienteNome:cliente.nome,
          usuario:auth.currentUser?.email||'—',
        }),
      });
      const d=await r.json();
      if(d.error){setErro(d.error);}
      else{
        alert(`✅ ${d.acao} enviada com sucesso à Secullum.`);
        setAcaoSel(null);setJustificativa('');
        consultar();
      }
    }catch(e){setErro('Erro: '+e.message);}
    setExecutando(false);
  }

  function fmt(x){
    if(x===null||x===undefined||x==='')return '—';
    if(typeof x==='string'&&/^\d{2}\/\d{2}\/\d{4}/.test(x))return x.split(' ')[0];
    return String(x);
  }

  const d=dados||null;
  const ocupacao=(()=>{
    const q=Number(d?.QuantidadePessoas??sync?.quantidadePessoas);
    const l=Number(d?.LimitePessoas??sync?.limitePessoas);
    if(!q||!l)return null;
    return {q,l,pct:Math.round((q/l)*100)};
  })();

  if(!ehAdmin)return null;

  return(
    <div style={{marginBottom:22}}>
      {/* Botão de destaque */}
      <div style={{background:'linear-gradient(135deg,#1a2a3a,#2c3e50)',borderRadius:12,padding:'14px 18px',
        display:'flex',alignItems:'center',gap:14,flexWrap:'wrap',boxShadow:'0 2px 10px rgba(0,0,0,.12)'}}>
        <div style={{width:38,height:38,borderRadius:10,background:'rgba(245,166,35,.18)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:18,flexShrink:0}}>☀️</div>
        <div style={{flex:1,minWidth:170}}>
          <div style={{fontWeight:700,fontSize:13,color:'#fff'}}>Status na Secullum</div>
          <div style={{fontSize:11,color:'rgba(255,255,255,.6)'}}>
            {cliente.codigoBancoSecullum
              ?<>Banco <strong style={{color:'#f5a623'}}>{cliente.codigoBancoSecullum}</strong>
                {sync?.atualizadoEm?` · última leitura em ${new Date(sync.atualizadoEm).toLocaleDateString('pt-BR')}`:''}</>
              :'Código do banco ainda não vinculado'}
          </div>
        </div>
        {ocupacao&&(
          <div style={{textAlign:'right',flexShrink:0}}>
            <div style={{fontSize:10,color:'rgba(255,255,255,.5)',textTransform:'uppercase',letterSpacing:.5}}>Funcionários</div>
            <div style={{fontSize:15,fontWeight:700,color:ocupacao.pct>=90?'#e74c3c':ocupacao.pct>=75?'#f5a623':'#52c41a'}}>
              {ocupacao.q} / {ocupacao.l}
            </div>
          </div>
        )}
        <button onClick={()=>{setAberto(a=>!a);if(!aberto&&cliente.codigoBancoSecullum&&!dados)consultar();}}
          style={{padding:'10px 20px',borderRadius:8,border:'none',background:'#f5a623',color:'#fff',fontWeight:700,cursor:'pointer',fontSize:13,flexShrink:0}}>
          {aberto?'Fechar':'🔍 Verificar status'}
        </button>
      </div>

      {aberto&&(
        <div style={{background:'#fff',border:'1px solid #e8eaed',borderTop:'none',borderRadius:'0 0 12px 12px',padding:'18px 20px'}}>
          {/* Código do banco */}
          <div style={{display:'flex',gap:8,alignItems:'flex-end',marginBottom:14,flexWrap:'wrap'}}>
            <div style={{flex:1,minWidth:160}}>
              <label style={lbl}>Código do banco na Secullum</label>
              <input style={fi} value={codigo} onChange={e=>setCodigo(e.target.value.replace(/\D/g,''))} placeholder="Ex: 157813"/>
            </div>
            <button onClick={salvarCodigo} disabled={salvandoCod||!codigo}
              style={{padding:'8px 14px',borderRadius:7,border:'1px solid #dde1e7',background:'#fff',cursor:'pointer',fontSize:12,fontWeight:600,color:'#4a4a4a'}}>
              {salvandoCod?'...':'Salvar código'}
            </button>
            <button onClick={consultar} disabled={carregando||!codigo}
              style={{padding:'8px 16px',borderRadius:7,border:'none',background:'#3498db',color:'#fff',fontWeight:700,cursor:'pointer',fontSize:12}}>
              {carregando?'Consultando...':'🔄 Consultar agora'}
            </button>
          </div>

          {erro&&<div style={{background:'#fee2e2',color:'#991b1b',borderRadius:7,padding:'9px 12px',fontSize:12,marginBottom:12}}>⚠ {erro}</div>}

          {/* Dados */}
          {(d||sync)&&(
            <div style={{marginBottom:16}}>
              <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(150px,1fr))',gap:8,marginBottom:10}}>
                {[
                  ['Razão social',   d?.RazaoSocial??sync?.razaoSocial],
                  ['Documento',      d?.Documento??sync?.documento],
                  ['Software',       d?.Software??sync?.software],
                  ['Plano',          d?.Plano??sync?.plano],
                  ['Funcionários',   `${d?.QuantidadePessoas??sync?.quantidadePessoas??'—'} de ${d?.LimitePessoas??sync?.limitePessoas??'—'}`],
                  ['Limite equip.',  d?.LimiteEquipamentos??sync?.limiteEquipamentos],
                  ['Período (meses)',d?.Periodo_meses??sync?.periodoMeses],
                  ['Ativado em',     d?.Ativado_em??sync?.ativadoEm],
                  ['Validade',       d?.Validade??sync?.validade],
                  ['Venc. contrato', d?.vencimentoContrato??sync?.vencimentoContrato],
                  ['Gestão arquivos',d?.RA_GestaoArquivos??sync?.gestaoArquivos],
                  ['Controle férias',d?.RA_Ferias??sync?.ferias],
                  ['Excluído em',    d?.DataExclusao??sync?.dataExclusao],
                ].map(([k,v])=>(
                  <div key={k} style={{background:'#f8f9fa',borderRadius:7,padding:'8px 11px'}}>
                    <div style={{fontSize:9,color:'#95a5a6',fontWeight:700,textTransform:'uppercase',letterSpacing:.5,marginBottom:2}}>{k}</div>
                    <div style={{fontSize:12,fontWeight:600,color:'#2c3e50'}}>{fmt(v)}</div>
                  </div>
                ))}
              </div>

              {/* Ocupação */}
              {ocupacao&&(
                <div style={{background:'#f8f9fa',borderRadius:8,padding:'10px 14px'}}>
                  <div style={{display:'flex',justifyContent:'space-between',fontSize:11,marginBottom:5}}>
                    <span style={{color:'#7f8c8d',fontWeight:600}}>Ocupação do contrato</span>
                    <span style={{fontWeight:700,color:ocupacao.pct>=90?'#e74c3c':ocupacao.pct>=75?'#f5a623':'#27ae60'}}>{ocupacao.pct}%</span>
                  </div>
                  <div style={{height:8,borderRadius:4,background:'#e8eaed',overflow:'hidden'}}>
                    <div style={{height:'100%',width:Math.min(ocupacao.pct,100)+'%',borderRadius:4,
                      background:ocupacao.pct>=90?'#e74c3c':ocupacao.pct>=75?'#f5a623':'#27ae60',transition:'width .5s'}}/>
                  </div>
                  {ocupacao.pct>=90&&<div style={{fontSize:11,color:'#e74c3c',marginTop:6,fontWeight:600}}>⚠ Perto do limite — vale oferecer upgrade de plano.</div>}
                </div>
              )}
            </div>
          )}

          {/* Ações */}
          {cliente.codigoBancoSecullum&&(
            <div>
              <div style={{fontSize:10,color:'#7f8c8d',fontWeight:700,textTransform:'uppercase',letterSpacing:.5,marginBottom:8}}>Ações administrativas</div>
              <div style={{display:'flex',gap:6,flexWrap:'wrap',marginBottom:12}}>
                {ACOES_SECULLUM.map(a=>(
                  <button key={a.tipo} onClick={()=>{setAcaoSel(acaoSel===a.tipo?null:a.tipo);setJustificativa('');setErro('');}}
                    style={{padding:'7px 13px',borderRadius:7,cursor:'pointer',fontSize:11,fontWeight:600,
                      border:`1px solid ${acaoSel===a.tipo?a.cor:'#dde1e7'}`,
                      background:acaoSel===a.tipo?a.cor:'#fff',color:acaoSel===a.tipo?'#fff':'#4a4a4a'}}>
                    {a.icone} {a.label}
                  </button>
                ))}
              </div>

              {acaoSel&&(
                <div style={{background:'#f8f9fa',borderRadius:8,padding:'12px 14px',
                  borderLeft:`3px solid ${ACOES_SECULLUM.find(a=>a.tipo===acaoSel)?.cor}`}}>
                  <div style={{fontSize:11,color:'#7f8c8d',marginBottom:8}}>
                    {ACOES_SECULLUM.find(a=>a.tipo===acaoSel)?.confirma}
                  </div>

                  {acaoSel===16&&(
                    <div style={{marginBottom:8}}>
                      <label style={lbl}>Modelo</label>
                      <select style={fi} value={modelo16}
                        onChange={e=>{setModelo16(e.target.value);setJustificativa(MODELOS_SEC16.find(m=>m.id===e.target.value)?.texto||'');}}>
                        {MODELOS_SEC16.map(m=><option key={m.id} value={m.id}>{m.label}</option>)}
                      </select>
                      <div style={{fontSize:10,color:'#b45309',marginTop:4}}>
                        A API não altera plano ou limite diretamente — isso abre um chamado para a Secullum processar.
                      </div>
                    </div>
                  )}

                  <label style={lbl}>Justificativa (obrigatória, até 350 caracteres)</label>
                  <textarea style={{...fi,minHeight:70,resize:'vertical'}} value={justificativa} maxLength={350}
                    onChange={e=>setJustificativa(e.target.value)}
                    placeholder="Descreva o motivo desta solicitação"/>
                  <div style={{fontSize:10,color:'#95a5a6',textAlign:'right',marginBottom:8}}>{justificativa.length}/350</div>

                  <div style={{display:'flex',gap:8}}>
                    <button onClick={executar} disabled={executando||!justificativa.trim()}
                      style={{padding:'8px 18px',borderRadius:7,border:'none',
                        background:executando?'#dde1e7':(ACOES_SECULLUM.find(a=>a.tipo===acaoSel)?.cor||'#3498db'),
                        color:'#fff',fontWeight:700,cursor:executando?'default':'pointer',fontSize:12}}>
                      {executando?'Enviando...':'Confirmar e enviar'}
                    </button>
                    <button onClick={()=>{setAcaoSel(null);setJustificativa('');}}
                      style={{padding:'8px 14px',borderRadius:7,border:'1px solid #dde1e7',background:'#fff',cursor:'pointer',fontSize:12,color:'#7f8c8d'}}>
                      Cancelar
                    </button>
                  </div>
                </div>
              )}
              <div style={{fontSize:10,color:'#95a5a6',marginTop:10}}>
                Toda ação fica registrada no histórico deste cliente, com o usuário e a justificativa.
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// --- CABEÇALHO DE SEÇÃO (padrão para cadastro e edição) ----------------------
// Cor fixa por assunto para virar memória visual: azul=identificação,
// roxo=endereço, laranja=valores, verde=contrato, ciano=equipamento.
const CORES_SECAO={
  dados:      {cor:'#3498db',icone:'👤'},
  endereco:   {cor:'#9b59b6',icone:'📍'},
  produtos:   {cor:'#e67e22',icone:'📦'},
  pagamento:  {cor:'#16a085',icone:'💳'},
  contrato:   {cor:'#27ae60',icone:'📄'},
  equipamento:{cor:'#0abde3',icone:'🚚'},
  lead:       {cor:'#e84393',icone:'🎯'},
  proposta:   {cor:'#e67e22',icone:'💼'},
  agenda:     {cor:'#8e44ad',icone:'📅'},
  historico:  {cor:'#7f8c8d',icone:'🕐'},
  contato:    {cor:'#25D366',icone:'💬'},
};
function CabecalhoSecao({tipo,titulo,subtitulo,acao}){
  const {cor,icone}=CORES_SECAO[tipo]||{cor:'#7f8c8d',icone:'•'};
  return(
    <div style={{display:'flex',alignItems:'center',gap:11,marginBottom:14,paddingBottom:12,borderBottom:'1px solid #f0f2f5'}}>
      <div style={{width:34,height:34,borderRadius:9,background:cor+'18',display:'flex',alignItems:'center',justifyContent:'center',fontSize:15,flexShrink:0}}>{icone}</div>
      <div style={{flex:1,minWidth:0}}>
        <div style={{fontWeight:700,fontSize:12,color:cor,textTransform:'uppercase',letterSpacing:.8}}>{titulo}</div>
        {subtitulo&&<div style={{fontSize:11,color:'#95a5a6',marginTop:1}}>{subtitulo}</div>}
      </div>
      {acao}
    </div>
  );
}
// Estilo do card de seção, com a barra colorida na lateral
function estiloSecao(tipo,base){
  const {cor}=CORES_SECAO[tipo]||{cor:'#7f8c8d'};
  return {...base,borderLeft:`4px solid ${cor}`,marginBottom:22};
}

// --- PRECIFICAÇÃO DE EQUIPAMENTOS --------------------------------------------
// Equipamentos antigos não têm preços cadastrados. Todas as funções abaixo
// tratam campos ausentes como 0 / sem promoção, para não quebrar dados legados.
function numVal(v){
  if(v===null||v===undefined||v==='')return 0;
  const n=parseFloat(String(v).replace(',','.'));
  return isNaN(n)?0:n;
}
// Promoção vigente hoje? Datas vazias significam "sem limite" daquele lado.
function equipEmPromocao(e,ref){
  if(!e)return false;
  const promo=numVal(e.valorPromocional);
  if(promo<=0)return false;
  const hoje=ref?new Date(ref):new Date();
  hoje.setHours(12,0,0,0);
  if(e.promoInicio){
    const ini=new Date(e.promoInicio+'T00:00:00');
    if(!isNaN(ini.getTime())&&hoje<ini)return false;
  }
  if(e.promoFim){
    const fim=new Date(e.promoFim+'T23:59:59');
    if(!isNaN(fim.getTime())&&hoje>fim)return false;
  }
  return true;
}
// Valor sugerido: promocional quando vigente, senão preço de venda.
function equipValorVigente(e){
  if(!e)return 0;
  if(equipEmPromocao(e))return numVal(e.valorPromocional);
  return numVal(e.precoVenda);
}
// ╔═ REGRA DE NEGÓCIO ═══════════════════════════════════════════════════════
// PISO DE VENDA: quando há valor promocional cadastrado, ele é o piso — não
// o preço de custo. Sem promocional, o piso passa a ser o custo. Vender abaixo
// disso exige liberação de um usuário admin, registrada no item.
// ═══════════════════════════════════════════════════════════════════════════
// Piso de venda: o valor promocional manda quando existe; sem promocional,
// o limite passa a ser o preço de custo. Zero significa "sem piso definido".
function equipPisoVenda(e){
  if(!e)return 0;
  const promo=numVal(e.valorPromocional);
  if(promo>0)return promo;
  return numVal(e.precoCusto);
}
function equipRotuloPiso(e){
  if(!e)return '';
  return numVal(e.valorPromocional)>0?'valor promocional':'preço de custo';
}
function fmtPeriodoPromo(e){
  const d=x=>{try{return new Date(x+'T12:00:00').toLocaleDateString('pt-BR');}catch(_){return x;}};
  if(e.promoInicio&&e.promoFim)return `${d(e.promoInicio)} a ${d(e.promoFim)}`;
  if(e.promoFim)return `até ${d(e.promoFim)}`;
  if(e.promoInicio)return `a partir de ${d(e.promoInicio)}`;
  return 'sem prazo definido';
}
// Selo visual de oferta
function SeloOferta({equip,style}){
  if(!equipEmPromocao(equip))return null;
  return(
    <span title={`Oferta válida ${fmtPeriodoPromo(equip)}`}
      style={{display:'inline-flex',alignItems:'center',gap:3,background:'linear-gradient(135deg,#e74c3c,#c0392b)',
        color:'#fff',padding:'1px 8px',borderRadius:10,fontSize:9,fontWeight:700,letterSpacing:.4,
        textTransform:'uppercase',flexShrink:0,...style}}>
      🔥 Oferta
    </span>
  );
}

function telParaWa(tel){
  // Remove tudo que não for número e adiciona código do Brasil
  const n=tel.replace(/\D/g,'');
  if(!n) return '';
  // Se começar com 0 remove
  const limpo=n.startsWith('0')?n.slice(1):n;
  return '55'+limpo;
}

function sortRecente(arr){
  return [...arr].sort((a,b)=>getDataTs(b)-getDataTs(a));
}


// --- EXPORT EXCEL/CSV --------------------------------------------------------
function exportarExcel(dados, nomeArquivo){
  const escape=v=>{
    if(v==null)return'';
    const s=String(v);
    if(s.includes(';')||s.includes('"')||s.includes('\n'))return`"${s.replace(/"/g,'""')}"`;
    return s;
  };
  const cab=['Data','Empresa','CNPJ','Contato','Telefone','Email','Cidade','UF','Funcionários','Equipamento','Plano','Vendedor','Status','Sistema/mês','Implantação','Equipamento R$','Total','Pagamento','1º Boleto'];
  const linhas=[cab,...dados.map(c=>{
    let dataFmt='';
    try{
      const d=c.data instanceof Date?c.data:(c.data?new Date(c.data):null);
      if(d&&!isNaN(d))dataFmt=`${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;
    }catch(e){}
    return[dataFmt,c.nome,c.cnpj,c.contato,c.tel,c.email,c.cidade||'',c.uf||c.estado||'',c.func,c.equipTipo,c.plano,c.vendedor,c.status,
      (c.vS||0).toFixed(2),(c.vI||0).toFixed(2),(c.vE||0).toFixed(2),(c.total||0).toFixed(2),c.pagamento,c.dtBoleto];
  })];
  const csv='\uFEFF'+linhas.map(l=>l.map(escape).join(';')).join('\n');
  const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');a.href=url;a.download=nomeArquivo+'.csv';a.click();
  URL.revokeObjectURL(url);
}

// --- GRÁFICO MRR MENSAL ------------------------------------------------------
function GraficoMRR({todos}){
  const anoAtual=new Date().getFullYear();
  const anos=[...new Set(todos.map(c=>c.ano).filter(Boolean))].sort();
  const [anoSel,setAnoSel]=useState(anos.includes(anoAtual)?anoAtual:(anos[anos.length-1]||anoAtual));
  const mesesData=MESES.map((_,m)=>{
    const cs=todos.filter(c=>c.ano===anoSel&&c.mes===m);
    return{m,fat:cs.filter(c=>c.status==='Faturado').reduce((s,c)=>s+c.total,0),agd:cs.filter(c=>c.status==='Aguardando').reduce((s,c)=>s+c.total,0),qtd:cs.length};
  });
  const maxVal=Math.max(...mesesData.map(d=>d.fat+d.agd),1);
  return(
    <div style={{background:C.card,borderRadius:8,padding:'16px',boxShadow:'0 1px 3px rgba(0,0,0,.08)',marginBottom:14}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:12}}>
        <div style={{fontWeight:700,fontSize:12,color:C.text,textTransform:'uppercase'}}>Evolução mensal de receita</div>
        <div style={{display:'flex',gap:4,flexWrap:'wrap'}}>
          {anos.map(a=><button key={a} onClick={()=>setAnoSel(a)} style={{padding:'3px 10px',borderRadius:4,border:'none',background:anoSel===a?C.blue:'#ecf0f1',color:anoSel===a?'#fff':C.textMuted,cursor:'pointer',fontSize:11,fontWeight:700}}>{a}</button>)}
        </div>
      </div>
      <div style={{display:'flex',alignItems:'flex-end',gap:3,height:130}}>
        {mesesData.map((d,i)=>(
          <div key={i} style={{flex:1,display:'flex',flexDirection:'column',alignItems:'center'}}>
            <div style={{width:'100%',display:'flex',flexDirection:'column',justifyContent:'flex-end',height:100}}>
              {d.agd>0&&<div title={'Aguardando: '+moeda(d.agd)} style={{width:'100%',background:C.orange,opacity:.7,minHeight:d.agd>0?2:0,height:Math.max((d.agd/maxVal)*100,d.agd>0?2:0)+'px'}}/>}
              <div title={'Faturado: '+moeda(d.fat)} style={{width:'100%',background:C.green,borderRadius:'3px 3px 0 0',minHeight:d.fat>0?3:0,height:Math.max((d.fat/maxVal)*100,d.fat>0?3:0)+'px'}}/>
            </div>
            <div style={{fontSize:8,color:C.textMuted,marginTop:3,textAlign:'center'}}>{MESES[i].slice(0,3)}</div>
            {d.qtd>0&&<div style={{fontSize:8,color:C.blue,fontWeight:700}}>{d.qtd}</div>}
          </div>
        ))}
      </div>
      <div style={{display:'flex',gap:14,marginTop:8,justifyContent:'flex-end'}}>
        <span style={{fontSize:10,color:C.textMuted,display:'flex',alignItems:'center',gap:4}}><span style={{width:10,height:10,background:C.green,borderRadius:2,display:'inline-block'}}/>Faturado</span>
        <span style={{fontSize:10,color:C.textMuted,display:'flex',alignItems:'center',gap:4}}><span style={{width:10,height:10,background:C.orange,borderRadius:2,display:'inline-block'}}/>Aguardando</span>
      </div>
    </div>
  );
}

// --- PAINEL DE ALERTAS -------------------------------------------------------
// --- PAINEL DE PENDÊNCIAS ----------------------------------------------------
// Abre a partir dos alertas do dashboard. Mostra, por cliente, onde o processo
// parou, há quanto tempo, o que já foi feito e o histórico registrado.
function ModalPendencias({tipo,itens,implantacoes,etapasConfig,onFechar,onAbrirCliente}){
  const [expandido,setExpandido]=useState(null);
  const [historicos,setHistoricos]=useState({});
  const [carregandoHist,setCarregandoHist]=useState(null);

  const TITULOS={
    atrasados:{t:'Implantações atrasadas',sub:'Prazo vencido e processo não finalizado',cor:'#e74c3c',icone:'⚠️'},
    semPrazo:{t:'Clientes sem prazo de implantação',sub:'Nenhuma data definida para conclusão',cor:'#f5a623',icone:'📅'},
    aguardando:{t:'Clientes aguardando faturamento',sub:'Venda fechada, cobrança ainda não concluída',cor:'#3498db',icone:'💰'},
  };
  const cfg=TITULOS[tipo]||TITULOS.atrasados;
  const ETAPAS_USE=(etapasConfig&&etapasConfig.length?etapasConfig:ETAPAS_DEFAULT);

  function diasDe(dataStr){
    if(!dataStr)return null;
    const d=new Date(String(dataStr).length<=10?dataStr+'T12:00:00':dataStr);
    if(isNaN(d.getTime()))return null;
    return Math.floor((Date.now()-d.getTime())/86400000);
  }
  function fmtData(x){
    if(!x)return '—';
    const d=new Date(String(x).length<=10?x+'T12:00:00':x);
    return isNaN(d.getTime())?'—':d.toLocaleDateString('pt-BR');
  }

  // Diagnóstico: onde parou e qual o gargalo
  function diagnostico(c){
    const impl=implantacoes[c.id]||{};
    const etapa=ETAPAS_USE.find(e=>e.id===impl.etapa);
    const diasPrazo=diasDe(impl.prazo);
    const linhas=[];
    if(tipo==='atrasados'){
      linhas.push({rot:'Gargalo',val:`Prazo venceu há ${diasPrazo} dia(s)`,cor:'#e74c3c'});
      linhas.push({rot:'Parado em',val:etapa?etapa.label:'(etapa não definida)'});
      linhas.push({rot:'Prazo',val:fmtData(impl.prazo)});
    }else if(tipo==='semPrazo'){
      linhas.push({rot:'Gargalo',val:'Sem data de conclusão definida',cor:'#f5a623'});
      linhas.push({rot:'Parado em',val:etapa?etapa.label:'(etapa não definida)'});
    }else{
      linhas.push({rot:'Gargalo',val:`Status "${labelStatus(c.status)}" há ${diasDe(c.criadoEm)??'?'} dia(s)`,cor:'#3498db'});
      linhas.push({rot:'Valor parado',val:moeda(c.total||0),cor:'#27ae60'});
      linhas.push({rot:'Forma de pagamento',val:c.pagamento||'—'});
      linhas.push({rot:'1º boleto',val:fmtData(c.dtBoleto)});
    }
    if(impl.responsavel)linhas.push({rot:'Responsável',val:impl.responsavel});
    if(c.vendedor&&c.vendedor!=='—')linhas.push({rot:'Vendedor',val:c.vendedor});
    return linhas;
  }

  // O que já foi feito: etapas anteriores à atual + comentários
  function jaFeito(c){
    const impl=implantacoes[c.id]||{};
    const idx=ETAPAS_USE.findIndex(e=>e.id===impl.etapa);
    const concluidas=idx>0?ETAPAS_USE.slice(0,idx).map(e=>e.label):[];
    return {concluidas,comentarios:impl.comentarios||[],setup:impl.descricaoSetup||''};
  }

  async function carregarHistorico(c){
    if(historicos[c.id])return;
    setCarregandoHist(c.id);
    try{
      const snap=await getDocs(collection(db,'historico_cliente'));
      const arr=[];
      snap.forEach(d=>{const x=d.data();if(x.clienteId===c.id)arr.push(x);});
      arr.sort((a,b)=>new Date(b.data||0)-new Date(a.data||0));
      setHistoricos(h=>({...h,[c.id]:arr}));
    }catch(e){setHistoricos(h=>({...h,[c.id]:[]}));}
    setCarregandoHist(null);
  }

  function abrir(c){
    const novo=expandido===c.id?null:c.id;
    setExpandido(novo);
    if(novo)carregarHistorico(c);
  }

  // Exporta o relatório em texto
  function exportar(){
    const linhas=[];
    linhas.push('='.repeat(60));
    linhas.push(cfg.t.toUpperCase());
    linhas.push(`Guion Informática — gerado em ${new Date().toLocaleString('pt-BR')}`);
    linhas.push(`${itens.length} pendência(s)`);
    linhas.push('='.repeat(60));
    itens.forEach((c,i)=>{
      linhas.push('');
      linhas.push(`${i+1}. ${c.nome}`);
      if(c.cnpj)linhas.push(`   CNPJ: ${c.cnpj}`);
      if(c.contato)linhas.push(`   Contato: ${c.contato}${c.tel?' — '+c.tel:''}`);
      diagnostico(c).forEach(l=>linhas.push(`   ${l.rot}: ${l.val}`));
      const f=jaFeito(c);
      if(f.concluidas.length)linhas.push(`   Já concluído: ${f.concluidas.join(' > ')}`);
      if(f.comentarios.length){
        linhas.push('   Comentários:');
        f.comentarios.slice(-5).forEach(cm=>linhas.push(`     - [${cm.data||''}] ${cm.texto||''}`));
      }
    });
    linhas.push('');
    linhas.push('='.repeat(60));
    const blob=new Blob([linhas.join('\n')],{type:'text/plain;charset=utf-8'});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    a.href=url;
    a.download=`pendencias-${tipo}-${new Date().toISOString().slice(0,10)}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  }

  return(
    <div style={{position:'fixed',inset:0,background:'rgba(0,0,0,.55)',zIndex:9999,display:'flex',alignItems:'flex-start',justifyContent:'center',padding:'30px 16px',overflowY:'auto'}}>
      <div style={{background:'#fff',borderRadius:12,maxWidth:880,width:'100%',boxShadow:'0 20px 60px rgba(0,0,0,.3)',overflow:'hidden'}}>
        {/* Cabeçalho */}
        <div style={{padding:'18px 24px',borderBottom:'1px solid #e8eaed',display:'flex',alignItems:'center',gap:12,flexWrap:'wrap'}}>
          <div style={{width:38,height:38,borderRadius:10,background:cfg.cor+'18',display:'flex',alignItems:'center',justifyContent:'center',fontSize:18,flexShrink:0}}>{cfg.icone}</div>
          <div style={{flex:1,minWidth:180}}>
            <div style={{fontWeight:700,fontSize:15,color:'#2c3e50'}}>{cfg.t}</div>
            <div style={{fontSize:11,color:'#95a5a6'}}>{cfg.sub} · {itens.length} pendência(s)</div>
          </div>
          <button onClick={exportar} style={{padding:'7px 14px',borderRadius:7,border:'1px solid #dde1e7',background:'#fff',cursor:'pointer',fontSize:12,fontWeight:600,color:'#4a4a4a'}}>
            📄 Baixar relatório
          </button>
          <button onClick={()=>window.print()} style={{padding:'7px 14px',borderRadius:7,border:'1px solid #dde1e7',background:'#fff',cursor:'pointer',fontSize:12,fontWeight:600,color:'#4a4a4a'}}>
            🖨️ Imprimir
          </button>
          <button onClick={onFechar} style={{background:'none',border:'none',cursor:'pointer',color:'#aaa',fontSize:22,lineHeight:1,flexShrink:0}}>×</button>
        </div>

        {/* Lista */}
        <div style={{maxHeight:'62vh',overflowY:'auto',padding:'14px 24px'}}>
          {itens.length===0&&<div style={{fontSize:13,color:'#7f8c8d',textAlign:'center',padding:'30px'}}>Nenhuma pendência.</div>}
          {itens.map(c=>{
            const aberto=expandido===c.id;
            const diag=diagnostico(c);
            const feito=jaFeito(c);
            const hist=historicos[c.id];
            return(
              <div key={c.id} style={{border:`1px solid ${aberto?cfg.cor+'66':'#e8eaed'}`,borderRadius:9,marginBottom:8,overflow:'hidden',background:aberto?'#fcfdfe':'#fff'}}>
                {/* Linha principal */}
                <div onClick={()=>abrir(c)} style={{padding:'12px 14px',cursor:'pointer',display:'flex',alignItems:'center',gap:12,flexWrap:'wrap',borderLeft:`4px solid ${cfg.cor}`}}>
                  <div style={{flex:1,minWidth:160}}>
                    <div style={{fontWeight:700,fontSize:13,color:'#2c3e50'}}>{c.nome}</div>
                    <div style={{fontSize:11,color:'#95a5a6'}}>
                      {c.contato||'—'}{c.tel?' · '+c.tel:''}
                    </div>
                  </div>
                  <div style={{textAlign:'right',flexShrink:0}}>
                    <div style={{fontSize:11,fontWeight:700,color:cfg.cor}}>{diag[0]?.val}</div>
                    {c.total>0&&<div style={{fontSize:11,color:'#27ae60',fontWeight:600}}>{moeda(c.total)}</div>}
                  </div>
                  <span style={{fontSize:14,color:'#bdc3c7',flexShrink:0}}>{aberto?'▲':'▼'}</span>
                </div>

                {/* Detalhes */}
                {aberto&&(
                  <div style={{padding:'0 16px 16px',borderTop:'1px solid #f0f2f5'}}>
                    {/* Diagnóstico */}
                    <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(160px,1fr))',gap:8,margin:'14px 0'}}>
                      {diag.map((l,i)=>(
                        <div key={i} style={{background:'#f8f9fa',borderRadius:7,padding:'8px 12px'}}>
                          <div style={{fontSize:9,color:'#95a5a6',fontWeight:700,textTransform:'uppercase',letterSpacing:.5,marginBottom:2}}>{l.rot}</div>
                          <div style={{fontSize:12,fontWeight:600,color:l.cor||'#2c3e50'}}>{l.val}</div>
                        </div>
                      ))}
                    </div>

                    {/* Já concluído */}
                    {feito.concluidas.length>0&&(
                      <div style={{marginBottom:12}}>
                        <div style={{fontSize:10,color:'#95a5a6',fontWeight:700,textTransform:'uppercase',letterSpacing:.5,marginBottom:5}}>✓ Já concluído</div>
                        <div style={{display:'flex',gap:6,flexWrap:'wrap'}}>
                          {feito.concluidas.map((e,i)=>(
                            <span key={i} style={{fontSize:11,background:'#f0fff4',color:'#276749',border:'1px solid #9ae6b4',padding:'3px 10px',borderRadius:12,fontWeight:600}}>{e}</span>
                          ))}
                        </div>
                      </div>
                    )}

                    {/* Setup */}
                    {feito.setup&&(
                      <div style={{marginBottom:12}}>
                        <div style={{fontSize:10,color:'#95a5a6',fontWeight:700,textTransform:'uppercase',letterSpacing:.5,marginBottom:5}}>Descrição do setup</div>
                        <div style={{fontSize:11,color:'#4a4a4a',background:'#f8f9fa',borderRadius:7,padding:'10px 12px',whiteSpace:'pre-wrap',maxHeight:130,overflowY:'auto',lineHeight:1.6}}>{feito.setup}</div>
                      </div>
                    )}

                    {/* Comentários */}
                    {feito.comentarios.length>0&&(
                      <div style={{marginBottom:12}}>
                        <div style={{fontSize:10,color:'#95a5a6',fontWeight:700,textTransform:'uppercase',letterSpacing:.5,marginBottom:5}}>Comentários do Kanban</div>
                        {feito.comentarios.slice(-4).reverse().map((cm,i)=>(
                          <div key={i} style={{background:'#f8f9fa',borderLeft:'3px solid #3498db',borderRadius:5,padding:'7px 11px',marginBottom:4}}>
                            <div style={{fontSize:11,color:'#2c3e50'}}>{cm.texto}</div>
                            <div style={{fontSize:9,color:'#aaa',marginTop:2}}>{cm.data} {cm.usuario?'· '+cm.usuario:''}</div>
                          </div>
                        ))}
                      </div>
                    )}

                    {/* Histórico do cliente */}
                    <div style={{marginBottom:12}}>
                      <div style={{fontSize:10,color:'#95a5a6',fontWeight:700,textTransform:'uppercase',letterSpacing:.5,marginBottom:5}}>Histórico do cliente</div>
                      {carregandoHist===c.id&&<div style={{fontSize:11,color:'#95a5a6'}}>Carregando...</div>}
                      {hist&&hist.length===0&&<div style={{fontSize:11,color:'#95a5a6'}}>Nenhum registro no histórico.</div>}
                      {hist&&hist.slice(0,6).map((h,i)=>(
                        <div key={i} style={{display:'flex',gap:9,padding:'5px 0',borderBottom:i<Math.min(hist.length,6)-1?'1px solid #f5f6fa':'none'}}>
                          <span style={{fontSize:10,color:'#aaa',minWidth:110,flexShrink:0}}>
                            {h.data?new Date(h.data).toLocaleDateString('pt-BR')+' '+new Date(h.data).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}):'—'}
                          </span>
                          <span style={{fontSize:11,color:'#4a4a4a',flex:1}}>{h.descricao||h.tipo}</span>
                        </div>
                      ))}
                    </div>

                    {/* Ações */}
                    <div style={{display:'flex',gap:8,flexWrap:'wrap'}}>
                      <button onClick={()=>{onAbrirCliente&&onAbrirCliente(c);onFechar();}}
                        style={{padding:'7px 16px',borderRadius:7,border:'none',background:cfg.cor,color:'#fff',fontWeight:700,cursor:'pointer',fontSize:12}}>
                        Abrir cliente →
                      </button>
                      {c.tel&&(
                        <a href={`https://wa.me/${telParaWa(c.tel)}?text=${encodeURIComponent('Olá! Passando para acompanhar o andamento do seu processo. 😊 — Guion Informática')}`}
                          target="_blank" rel="noopener noreferrer"
                          style={{padding:'7px 16px',borderRadius:7,background:'#25D366',color:'#fff',fontWeight:700,fontSize:12,textDecoration:'none'}}>
                          WhatsApp
                        </a>
                      )}
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function PainelAlertas({todos,implantacoes,onVerImplantacao,etapasConfig,onAbrirCliente}){
  const [modal,setModal]=useState(null); // 'atrasados' | 'semPrazo' | 'aguardando'
  const hoje=new Date();hoje.setHours(0,0,0,0);
  const atrasados=todos.filter(c=>{
    const impl=implantacoes[c.id]||{};
    if(impl.etapa==='processo_finalizado'||!impl.prazo)return false;
    return new Date(impl.prazo+'T12:00:00')<hoje;
  });
  const semPrazo=todos.filter(c=>{
    const impl=implantacoes[c.id]||{};
    return impl.etapa!=='processo_finalizado'&&!impl.prazo;
  });
  const STATUS_AGD=['Links enviados','Aguardando','Faturado parcial'];
  const agdFat=todos.filter(c=>STATUS_AGD.includes(c.status));
  const totAgd=agdFat.reduce((s,c)=>s+c.total,0);
  if(!atrasados.length&&!semPrazo.length&&!agdFat.length)return null;
  return(
    <div style={{marginBottom:14}}>
      {atrasados.length>0&&(
        <div style={{background:'#fef2f2',border:'1px solid #fecaca',borderRadius:8,padding:'10px 14px',marginBottom:8,display:'flex',justifyContent:'space-between',alignItems:'center'}}>
          <div style={{display:'flex',alignItems:'center',gap:8}}>
            <i className="ti ti-alert-triangle" style={{color:C.red,fontSize:16}}/>
            <span style={{fontSize:13,fontWeight:700,color:C.red}}>{atrasados.length} implantação(ões) atrasada(s)</span>
          </div>
          <div style={{display:'flex',gap:6}}>
            <button onClick={()=>setModal('atrasados')} style={{background:C.red,color:'#fff',border:'none',borderRadius:5,padding:'4px 12px',cursor:'pointer',fontSize:11,fontWeight:700}}>Ver detalhes →</button>
            <button onClick={onVerImplantacao} style={{background:'#fff',color:C.red,border:`1px solid ${C.red}`,borderRadius:5,padding:'4px 10px',cursor:'pointer',fontSize:11,fontWeight:700}}>Kanban</button>
          </div>
        </div>
      )}
      {semPrazo.length>0&&(
        <div style={{background:'#fffbeb',border:'1px solid #fde68a',borderRadius:8,padding:'10px 14px',marginBottom:8,display:'flex',justifyContent:'space-between',alignItems:'center'}}>
          <div style={{display:'flex',alignItems:'center',gap:8}}>
            <i className="ti ti-clock-exclamation" style={{color:C.orange,fontSize:16}}/>
            <span style={{fontSize:13,fontWeight:700,color:C.orange}}>{semPrazo.length} cliente(s) sem prazo de implantação</span>
          </div>
          <div style={{display:'flex',gap:6}}>
            <button onClick={()=>setModal('semPrazo')} style={{background:C.orange,color:'#fff',border:'none',borderRadius:5,padding:'4px 12px',cursor:'pointer',fontSize:11,fontWeight:700}}>Ver detalhes →</button>
            <button onClick={onVerImplantacao} style={{background:'#fff',color:C.orange,border:`1px solid ${C.orange}`,borderRadius:5,padding:'4px 10px',cursor:'pointer',fontSize:11,fontWeight:700}}>Kanban</button>
          </div>
        </div>
      )}
      {agdFat.length>0&&(
        <div style={{background:'#eff6ff',border:'1px solid #bfdbfe',borderRadius:8,padding:'10px 14px',display:'flex',justifyContent:'space-between',alignItems:'center'}}>
          <div style={{display:'flex',alignItems:'center',gap:8}}>
            <i className="ti ti-currency-dollar" style={{color:C.blue,fontSize:16}}/>
            <div style={{display:'flex',flexDirection:'column',gap:2}}>
              <span style={{fontSize:13,fontWeight:700,color:C.blue}}>{agdFat.length} cliente(s) pendente(s) — {moeda(totAgd)}</span>
              <div style={{display:'flex',gap:10,flexWrap:'wrap',marginTop:2}}>
                {[
                  {s:'Links enviados', emoji:'⚡', c:'#3498db'},
                  {s:'Aguardando',     emoji:'⏳', c:'#f5a623'},
                  {s:'Faturado parcial',emoji:'💰',c:'#f39c12'},
                ].map(({s,emoji,c})=>{
                  const qtd=todos.filter(x=>x.status===s).length;
                  if(!qtd)return null;
                  return<span key={s} style={{fontSize:10,color:c,fontWeight:700}}>{emoji} {s}: {qtd}</span>;
                })}
              </div>
            </div>
          </div>
          <button onClick={()=>setModal('aguardando')} style={{background:C.blue,color:'#fff',border:'none',borderRadius:5,padding:'4px 12px',cursor:'pointer',fontSize:11,fontWeight:700,flexShrink:0}}>Ver detalhes →</button>
        </div>
      )}

      {modal&&(
        <ModalPendencias
          tipo={modal}
          itens={modal==='atrasados'?atrasados:modal==='semPrazo'?semPrazo:agdFat}
          implantacoes={implantacoes}
          etapasConfig={etapasConfig}
          onFechar={()=>setModal(null)}
          onAbrirCliente={onAbrirCliente}
        />
      )}
    </div>
  );
}

// --- META MENSAL -------------------------------------------------------------
function CardMeta({titulo,realizado,meta,onSetMeta,cor,icone}){
  const pct=meta>0?Math.min(Math.round((realizado/meta)*100),100):0;
  const falta=meta>0?Math.max(meta-realizado,0):0;
  const atingiu=meta>0&&realizado>=meta;
  const [editando,setEditando]=useState(false);
  const [val,setVal]=useState(String(meta||''));

  // Cor da barra acompanha o progresso
  const corBarra=atingiu?'#27ae60':pct>=70?cor:'#f5a623';

  const frase=meta<=0?'Defina sua meta para acompanhar o progresso'
    :atingiu?'🏆 Meta atingida! Parabéns, equipe!'
    :pct>=90?'🔥 Quase lá! Último esforço'
    :pct>=70?'💪 Ótimo ritmo! Continue assim'
    :pct>=50?'📈 Na metade do caminho'
    :pct>=25?'⚡ Bora acelerar'
    :'🚀 O céu é o limite! Vamos lá';

  return(
    <div style={{
      flex:1,minWidth:270,borderRadius:12,overflow:'hidden',position:'relative',
      background:atingiu?'#f2fbf5':'#fff',
      border:`1px solid ${atingiu?'#a7e3bd':'#e8eaed'}`,
      boxShadow:'0 1px 4px rgba(0,0,0,.06)',
    }}>
      {/* Faixa superior na cor do card */}
      <div style={{height:3,background:atingiu?'#27ae60':cor}}/>

      <div style={{padding:'16px 20px'}}>
        {/* Cabeçalho */}
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',marginBottom:14,gap:10}}>
          <div style={{display:'flex',alignItems:'center',gap:9,minWidth:0}}>
            <div style={{width:32,height:32,borderRadius:9,background:(atingiu?'#27ae60':cor)+'18',
              display:'flex',alignItems:'center',justifyContent:'center',fontSize:15,flexShrink:0}}>{icone}</div>
            <div style={{minWidth:0}}>
              <div style={{fontWeight:700,fontSize:10,color:'#95a5a6',textTransform:'uppercase',letterSpacing:1,marginBottom:1}}>{titulo}</div>
              <div style={{fontSize:22,fontWeight:700,color:atingiu?'#1e8449':'#2c3e50',letterSpacing:-.4,lineHeight:1.1}}>{moeda(realizado)}</div>
            </div>
          </div>
          <div style={{textAlign:'right',flexShrink:0}}>
            {!editando?(
              <div>
                <div style={{fontSize:9,color:'#b2bec3',marginBottom:2,textTransform:'uppercase',letterSpacing:.5}}>Meta</div>
                <div style={{display:'flex',alignItems:'center',gap:5,justifyContent:'flex-end'}}>
                  <span style={{fontSize:13,fontWeight:600,color:'#7f8c8d'}}>{meta>0?moeda(meta):'—'}</span>
                  <button onClick={()=>{setVal(String(meta||''));setEditando(true);}}
                    title="Editar meta"
                    style={{background:'#f5f6fa',border:'1px solid #e8eaed',borderRadius:6,padding:'3px 6px',cursor:'pointer',fontSize:10,lineHeight:1}}>✏️</button>
                </div>
              </div>
            ):(
              <div style={{display:'flex',gap:4,alignItems:'center'}}>
                <input value={val} autoFocus onChange={e=>setVal(e.target.value)}
                  onKeyDown={e=>{if(e.key==='Enter'){onSetMeta(parseFloat(String(val).replace(',','.'))||0);setEditando(false);}if(e.key==='Escape')setEditando(false);}}
                  placeholder="Ex: 5000"
                  style={{padding:'5px 8px',borderRadius:6,border:'1.5px solid '+cor,fontSize:12,width:92,outline:'none',color:'#2c3e50'}}/>
                <button onClick={()=>{onSetMeta(parseFloat(String(val).replace(',','.'))||0);setEditando(false);}}
                  style={{background:'#27ae60',color:'#fff',border:'none',borderRadius:6,padding:'5px 10px',cursor:'pointer',fontSize:11,fontWeight:700}}>OK</button>
                <button onClick={()=>setEditando(false)}
                  style={{background:'#f5f6fa',border:'1px solid #e8eaed',borderRadius:6,padding:'5px 8px',cursor:'pointer',color:'#95a5a6',fontSize:11}}>✕</button>
              </div>
            )}
          </div>
        </div>

        {/* Progresso */}
        {meta>0&&(
          <div style={{marginBottom:11}}>
            <div style={{height:8,borderRadius:4,background:'#f0f2f5',overflow:'hidden',marginBottom:6}}>
              <div style={{
                height:'100%',borderRadius:4,
                background:atingiu?'linear-gradient(90deg,#27ae60,#52c41a)':`linear-gradient(90deg,${corBarra},${corBarra}bb)`,
                width:pct+'%',transition:'width .6s cubic-bezier(.4,0,.2,1)',
              }}/>
            </div>
            <div style={{display:'flex',justifyContent:'space-between',fontSize:10}}>
              <span style={{color:'#7f8c8d',fontWeight:600}}>{pct}% atingido</span>
              {!atingiu&&<span style={{color:'#e67e22',fontWeight:600}}>Faltam {moeda(falta)}</span>}
              {atingiu&&<span style={{color:'#27ae60',fontWeight:700}}>✓ Superou a meta!</span>}
            </div>
          </div>
        )}

        {/* Frase */}
        <div style={{
          background:atingiu?'#dff5e6':'#f8f9fa',borderRadius:7,padding:'7px 12px',
          fontSize:11,color:atingiu?'#1e8449':'#7f8c8d',fontWeight:600,textAlign:'center',
        }}>
          {frase}
        </div>
      </div>
    </div>
  );
}

function DuplasMetas({todos,metaSistema,metaEquip,onSetMetaSistema,onSetMetaEquip}){
  const hoje=new Date();
  const mesAtual=hoje.getMonth(),anoAtual=hoje.getFullYear();
  const csMes=todos.filter(c=>c.mes===mesAtual&&c.ano===anoAtual&&c.status==='Faturado');
  const realSist=csMes.reduce((s,c)=>s+(parseFloat(c.vS)||0),0);
  const realEquip=csMes.reduce((s,c)=>s+(parseFloat(c.vE)||0),0);
  const totalMes=realSist+realEquip;
  const totalMeta=(metaSistema||0)+(metaEquip||0);
  const pctTotal=totalMeta>0?Math.min(Math.round((totalMes/totalMeta)*100),100):0;
  return(
    <div style={{marginBottom:16}}>
      {/* Header da seção */}
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:10}}>
        <div style={{display:'flex',alignItems:'center',gap:8}}>
          <div style={{width:3,height:16,borderRadius:2,background:'#f5a623'}}/>
          <span style={{fontSize:11,color:'#4a4a4a',fontWeight:700,textTransform:'uppercase',letterSpacing:.8}}>Metas — {MESES[mesAtual]}/{anoAtual}</span>
        </div>
        {totalMeta>0&&(
          <div style={{display:'flex',alignItems:'center',gap:6,background:'#f5f6fa',borderRadius:20,padding:'3px 12px',border:'1px solid #e8eaed'}}>
            <span style={{fontSize:10,color:'#7f8c8d'}}>Total geral:</span>
            <span style={{fontSize:12,fontWeight:700,color:pctTotal>=100?'#27ae60':'#f5a623'}}>{moeda(totalMes)}</span>
            <span style={{fontSize:10,color:'#aaa'}}>/ {moeda(totalMeta)}</span>
            <span style={{fontSize:11,fontWeight:700,color:pctTotal>=100?'#27ae60':'#4a4a4a'}}>{pctTotal}%</span>
          </div>
        )}
      </div>
      <div style={{display:'flex',gap:12,flexWrap:'wrap'}}>
        <CardMeta titulo="Meta Sistema" icone="☁️" realizado={realSist} meta={metaSistema} onSetMeta={onSetMetaSistema} cor="#9b59b6"/>
        <CardMeta titulo="Meta Equipamentos" icone="💻" realizado={realEquip} meta={metaEquip} onSetMeta={onSetMetaEquip} cor="#1abc9c"/>
      </div>
    </div>
  );
}

// --- PÁGINA DE RELATÓRIOS -----------------------------------------------------
function RelatoriosView({todos,implantacoes}){
  const [anoRel,setAnoRel]=useState('Todos');
  const [mesRel,setMesRel]=useState('Todos');
  const [vendRel,setVendRel]=useState('Todos');
  const [planoRel,setPlanoRel]=useState('Todos');
  const [statusRel,setStatusRel]=useState('Todos');
  const [busca,setBusca]=useState('');
  const [abaRel,setAbaRel]=useState('pendentes'); // 'pendentes' | 'todos'
  const [sortCol,setSortCol]=useState('data');
  const [sortDir,setSortDir]=useState('desc');

  const anosDisp=[...new Set(todos.map(c=>c.ano).filter(Boolean))].sort();
  const vendedores=['Todos',...new Set(todos.map(c=>c.vendedor).filter(v=>v&&v!=='—'))].sort();
  const fi={padding:'6px 10px',borderRadius:5,border:'1px solid #dde1e7',fontSize:12,color:'#2c3e50',background:'#fff'};

  // Apenas clientes reais (não base histórica)
  const reais=todos.filter(c=>!c._base);

  const dadosFiltrados=reais.filter(c=>{
    if(anoRel!=='Todos'&&c.ano!==+anoRel)return false;
    if(mesRel!=='Todos'&&c.mes!==+mesRel)return false;
    if(vendRel!=='Todos'&&c.vendedor!==vendRel)return false;
    if(planoRel!=='Todos'&&c.plano!==planoRel)return false;
    if(statusRel!=='Todos'&&c.status!==statusRel)return false;
    if(busca.trim()){
      const b=busca.toLowerCase();
      if(!c.nome?.toLowerCase().includes(b)&&!c.cnpj?.includes(b)&&!c.contato?.toLowerCase().includes(b)&&!c.vendedor?.toLowerCase().includes(b))return false;
    }
    return true;
  });

  // Pendentes = qualquer cobrança ainda não totalmente resolvida
  function getPendencias(c){
    const p=[];
    // Implantação
    if(parseFloat(c.vI)>0){
      const st=c.asaas_status_impl||'';
      if(!st||st==='PENDING'||st==='OVERDUE'||st==='')p.push({tipo:'impl',label:'Implantação',valor:parseFloat(c.vI),forma:c.pagamentoI||'Boleto',parcelas:c.parcelasI||1,status:st||'SEM_LINK'});
    }
    // Equipamento
    if(parseFloat(c.vE)>0){
      const st=c.asaas_status_equip||'';
      if(!st||st==='PENDING'||st==='OVERDUE'||st==='')p.push({tipo:'equip',label:'Equipamento',valor:parseFloat(c.vE),forma:c.pagamentoE||'Boleto',parcelas:c.parcelasE||1,status:st||'SEM_LINK'});
    }
    // Sistema
    if(parseFloat(c.vS)>0){
      const st=c.asaas_status_sistema||c.asaas_status||'';
      if(!c.asaas_id||!st||st==='PENDING'||st==='OVERDUE'||st==='')p.push({tipo:'sistema',label:'Sistema',valor:parseFloat(c.vS),forma:'Boleto',parcelas:1,status:st||'SEM_FATURAMENTO',recorrente:true});
    }
    return p;
  }

  const pendentes=dadosFiltrados.filter(c=>getPendencias(c).length>0);
  const inadimplentes=dadosFiltrados.filter(c=>c.status==='Inadimplente'||(c.asaas_status_sistema==='OVERDUE'||c.asaas_status_impl==='OVERDUE'||c.asaas_status_equip==='OVERDUE'));
  const semAsaas=dadosFiltrados.filter(c=>!c.asaas_id&&(parseFloat(c.vI)>0||parseFloat(c.vE)>0||parseFloat(c.vS)>0));
  const aguardBoleto=dadosFiltrados.filter(c=>c.status==='Aguardando');
  const linksEnviados=dadosFiltrados.filter(c=>c.status==='Links enviados');

  const totPendentes=pendentes.reduce((s,c)=>s+getPendencias(c).reduce((a,p)=>a+p.valor,0),0);
  const totInadimpl=inadimplentes.reduce((s,c)=>s+(c.vS||0),0);

  function sortDados(arr){
    return [...arr].sort((a,b)=>{
      let va,vb;
      if(sortCol==='nome'){va=a.nome||'';vb=b.nome||'';}
      else if(sortCol==='vendedor'){va=a.vendedor||'';vb=b.vendedor||'';}
      else if(sortCol==='total'){va=a.total||0;vb=b.total||0;}
      else if(sortCol==='status'){va=a.status||'';vb=b.status||'';}
      else if(sortCol==='vS'){va=a.vS||0;vb=b.vS||0;}
      else if(sortCol==='vI'){va=a.vI||0;vb=b.vI||0;}
      else if(sortCol==='vE'){va=a.vE||0;vb=b.vE||0;}
      else{va=getDataTs(a);vb=getDataTs(b);}
      if(va<vb)return sortDir==='asc'?-1:1;
      if(va>vb)return sortDir==='asc'?1:-1;
      return 0;
    });
  }

  function toggleSort(col){
    if(sortCol===col)setSortDir(d=>d==='asc'?'desc':'asc');
    else{setSortCol(col);setSortDir('asc');}
  }

  function SortTh({col,children,style={}}){
    const ativo=sortCol===col;
    return(
      <th onClick={()=>toggleSort(col)} style={{padding:'8px 10px',textAlign:'left',fontSize:10,color:ativo?C.blue:C.textMuted,fontWeight:700,textTransform:'uppercase',whiteSpace:'nowrap',cursor:'pointer',userSelect:'none',...style}}>
        {children}{ativo?(sortDir==='asc'?' ↑':' ↓'):''}
      </th>
    );
  }

  function badgeAsaas(st,size='small'){
    const s=ASAAS_STATUS[st]||ASAAS_STATUS.SEM_FATURAMENTO;
    const p=size==='small'?'1px 5px':'2px 8px';
    return<span style={{background:s.color+'22',color:s.color,border:`1px solid ${s.color}44`,borderRadius:8,padding:p,fontSize:9,fontWeight:700,whiteSpace:'nowrap'}}>{s.emoji} {s.label}</span>;
  }

  function badgePendencia(p){
    const cores={SEM_LINK:'#95a5a6',SEM_FATURAMENTO:'#3498db',PENDING:'#f5a623',OVERDUE:'#e74c3c'};
    const labels={SEM_LINK:'Sem link',SEM_FATURAMENTO:'Sem faturamento',PENDING:'Pendente',OVERDUE:'Vencido'};
    const emojis={SEM_LINK:'⬜',SEM_FATURAMENTO:'🔵',PENDING:'🟡',OVERDUE:'🔴'};
    const cor=cores[p.status]||'#95a5a6';
    const lbl=labels[p.status]||p.status;
    const em=emojis[p.status]||'❓';
    return<span style={{background:cor+'22',color:cor,border:`1px solid ${cor}44`,borderRadius:6,padding:'1px 5px',fontSize:9,fontWeight:700,whiteSpace:'nowrap'}}>{em} {lbl}</span>;
  }

  function nomeArq(){
    const p=['relatorio'];
    if(anoRel!=='Todos')p.push(anoRel);
    if(mesRel!=='Todos')p.push(MESES[+mesRel]);
    if(vendRel!=='Todos')p.push(vendRel.replace(/\s/g,'_'));
    if(planoRel!=='Todos')p.push(planoRel);
    if(statusRel!=='Todos')p.push(statusRel);
    return p.join('_');
  }

  const porEtapa=ETAPAS.map(e=>{
    const cs=todos.filter(c=>{const impl=implantacoes[c.id]||{};return impl.etapa===e.id;});
    return{...e,qtd:cs.length,clientes:cs};
  }).filter(e=>e.qtd>0);

  const listaOrdenada=sortDados(abaRel==='pendentes'?pendentes:dadosFiltrados);

  return(
    <div>
      {/* ── CARDS DE ALERTA ── */}
      <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(150px,1fr))',gap:10,marginBottom:14}}>
        <div onClick={()=>{setAbaRel('pendentes');setStatusRel('Todos');}} style={{background:'#fffbeb',border:'2px solid #f5a623',borderRadius:8,padding:'12px 14px',cursor:'pointer',transition:'box-shadow .15s'}}
          onMouseEnter={e=>e.currentTarget.style.boxShadow='0 2px 8px rgba(245,166,35,.3)'}
          onMouseLeave={e=>e.currentTarget.style.boxShadow='none'}>
          <div style={{fontSize:10,color:'#b45309',fontWeight:700,textTransform:'uppercase',marginBottom:4}}>⏳ Com pendência</div>
          <div style={{fontSize:22,fontWeight:700,color:'#b45309'}}>{pendentes.length}</div>
          <div style={{fontSize:10,color:'#b45309',marginTop:2}}>{moeda(totPendentes)}</div>
        </div>
        <div onClick={()=>{setAbaRel('pendentes');setStatusRel('Inadimplente');}} style={{background:'#fff5f5',border:'2px solid #e74c3c',borderRadius:8,padding:'12px 14px',cursor:'pointer',transition:'box-shadow .15s'}}
          onMouseEnter={e=>e.currentTarget.style.boxShadow='0 2px 8px rgba(231,76,60,.3)'}
          onMouseLeave={e=>e.currentTarget.style.boxShadow='none'}>
          <div style={{fontSize:10,color:'#c0392b',fontWeight:700,textTransform:'uppercase',marginBottom:4}}>🔴 Inadimplentes</div>
          <div style={{fontSize:22,fontWeight:700,color:'#c0392b'}}>{inadimplentes.length}</div>
          <div style={{fontSize:10,color:'#c0392b',marginTop:2}}>{moeda(totInadimpl)}/mês em risco</div>
        </div>
        <div onClick={()=>{setAbaRel('pendentes');setStatusRel('Aguardando');}} style={{background:'#fef9f0',border:'1px solid #f39c12',borderRadius:8,padding:'12px 14px',cursor:'pointer'}}>
          <div style={{fontSize:10,color:'#e67e22',fontWeight:700,textTransform:'uppercase',marginBottom:4}}>📄 Aguard. boleto</div>
          <div style={{fontSize:22,fontWeight:700,color:'#e67e22'}}>{aguardBoleto.length}</div>
        </div>
        <div onClick={()=>{setAbaRel('pendentes');setStatusRel('Links enviados');}} style={{background:'#eef6ff',border:'1px solid #3498db',borderRadius:8,padding:'12px 14px',cursor:'pointer'}}>
          <div style={{fontSize:10,color:'#2980b9',fontWeight:700,textTransform:'uppercase',marginBottom:4}}>⚡ Links enviados</div>
          <div style={{fontSize:22,fontWeight:700,color:'#2980b9'}}>{linksEnviados.length}</div>
        </div>
        <div style={{background:'#f8f9fa',border:'1px solid #dde1e7',borderRadius:8,padding:'12px 14px'}}>
          <div style={{fontSize:10,color:C.textMuted,fontWeight:700,textTransform:'uppercase',marginBottom:4}}>🔵 Sem Asaas</div>
          <div style={{fontSize:22,fontWeight:700,color:C.textMuted}}>{semAsaas.length}</div>
        </div>
        <div style={{background:'#f0fff4',border:'1px solid #27ae60',borderRadius:8,padding:'12px 14px'}}>
          <div style={{fontSize:10,color:'#27ae60',fontWeight:700,textTransform:'uppercase',marginBottom:4}}>✅ Faturados</div>
          <div style={{fontSize:22,fontWeight:700,color:'#27ae60'}}>{dadosFiltrados.filter(c=>c.status==='Faturado').length}</div>
        </div>
      </div>

      {/* ── FILTROS ── */}
      <div style={{background:C.card,borderRadius:8,padding:'14px 16px',boxShadow:'0 1px 3px rgba(0,0,0,.08)',marginBottom:14}}>
        <div style={{display:'flex',gap:8,flexWrap:'wrap',alignItems:'center'}}>
          <input value={busca} onChange={e=>setBusca(e.target.value)} placeholder="🔍 Buscar empresa, CNPJ, contato..." style={{...fi,minWidth:220,flex:1}}/>
          <select value={anoRel} onChange={e=>setAnoRel(e.target.value)} style={fi}><option value="Todos">Todos os anos</option>{anosDisp.map(a=><option key={a}>{a}</option>)}</select>
          <select value={mesRel} onChange={e=>setMesRel(e.target.value)} style={fi}><option value="Todos">Todos os meses</option>{MESES.map((m,i)=><option key={i} value={i}>{m}</option>)}</select>
          <select value={vendRel} onChange={e=>setVendRel(e.target.value)} style={fi}>{vendedores.map(v=><option key={v}>{v}</option>)}</select>
          <select value={planoRel} onChange={e=>setPlanoRel(e.target.value)} style={fi}><option value="Todos">Todos os planos</option>{PLANOS.map(p=><option key={p}>{p}</option>)}</select>
          <select value={statusRel} onChange={e=>setStatusRel(e.target.value)} style={fi}>
            <option value="Todos">Todos os status</option>
            {STATUS_CLIENTE.map(s=><option key={s.id} value={s.id}>{s.label}</option>)}
          </select>
          {(busca||anoRel!=='Todos'||mesRel!=='Todos'||vendRel!=='Todos'||planoRel!=='Todos'||statusRel!=='Todos')&&(
            <button onClick={()=>{setBusca('');setAnoRel('Todos');setMesRel('Todos');setVendRel('Todos');setPlanoRel('Todos');setStatusRel('Todos');}} style={{padding:'6px 12px',borderRadius:5,border:'none',background:'#ecf0f1',cursor:'pointer',fontSize:11,color:C.text}}>✕ Limpar</button>
          )}
        </div>
      </div>

      {/* ── ABAS ── */}
      <div style={{display:'flex',gap:0,marginBottom:0,borderBottom:'2px solid '+C.border}}>
        {[['pendentes',`⏳ Com pendência (${pendentes.length})`],['todos',`📋 Todos os clientes (${dadosFiltrados.length})`]].map(([id,lbl])=>(
          <button key={id} onClick={()=>setAbaRel(id)} style={{padding:'9px 18px',border:'none',borderBottom:`2px solid ${abaRel===id?C.blue:'transparent'}`,background:'transparent',cursor:'pointer',fontSize:12,fontWeight:abaRel===id?700:400,color:abaRel===id?C.blue:C.textMuted,marginBottom:'-2px'}}>
            {lbl}
          </button>
        ))}
        <div style={{flex:1}}/>
        <div style={{display:'flex',gap:8,alignItems:'center',paddingBottom:4}}>
          <button onClick={()=>exportarExcel(abaRel==='pendentes'?pendentes:dadosFiltrados,nomeArq()+'_clientes')} style={{display:'flex',alignItems:'center',gap:5,padding:'6px 12px',borderRadius:6,border:'none',background:C.green,color:'#fff',fontWeight:700,cursor:'pointer',fontSize:11}}>
            <i className="ti ti-file-spreadsheet"/> Exportar .csv
          </button>
        </div>
      </div>

      {/* ── TABELA PRINCIPAL ── */}
      <div style={{background:C.card,borderRadius:'0 0 8px 8px',boxShadow:'0 1px 3px rgba(0,0,0,.08)',overflow:'hidden',marginBottom:14}}>
        <div style={{overflowX:'auto'}}>
          <table style={{width:'100%',borderCollapse:'collapse',minWidth:900}}>
            <thead>
              <tr style={{background:'#f8f9fa'}}>
                <SortTh col="nome">Empresa</SortTh>
                <th style={{padding:'8px 10px',textAlign:'left',fontSize:10,color:C.textMuted,fontWeight:700,textTransform:'uppercase',whiteSpace:'nowrap'}}>CNPJ</th>
                <th style={{padding:'8px 10px',textAlign:'left',fontSize:10,color:C.textMuted,fontWeight:700,textTransform:'uppercase',whiteSpace:'nowrap'}}>Contato / Tel</th>
                <SortTh col="vendedor">Vendedor</SortTh>
                <th style={{padding:'8px 10px',textAlign:'left',fontSize:10,color:C.textMuted,fontWeight:700,textTransform:'uppercase',whiteSpace:'nowrap'}}>Plano</th>
                <SortTh col="status">Status CRM</SortTh>
                <th style={{padding:'8px 10px',textAlign:'left',fontSize:10,color:C.textMuted,fontWeight:700,textTransform:'uppercase',whiteSpace:'nowrap'}}>Asaas</th>
                {abaRel==='pendentes'&&<th style={{padding:'8px 10px',textAlign:'left',fontSize:10,color:C.textMuted,fontWeight:700,textTransform:'uppercase',whiteSpace:'nowrap'}}>O que falta</th>}
                <SortTh col="vI" style={{textAlign:'right'}}>Impl.</SortTh>
                <SortTh col="vE" style={{textAlign:'right'}}>Equip.</SortTh>
                <SortTh col="vS" style={{textAlign:'right'}}>Sist./mês</SortTh>
                <SortTh col="total" style={{textAlign:'right'}}>Total</SortTh>
              </tr>
            </thead>
            <tbody>
              {listaOrdenada.length===0&&(
                <tr><td colSpan={abaRel==='pendentes'?12:11} style={{padding:'24px',textAlign:'center',color:C.textMuted,fontSize:12}}>
                  {abaRel==='pendentes'?'✅ Nenhuma pendência financeira encontrada!':'Nenhum cliente encontrado com os filtros aplicados.'}
                </td></tr>
              )}
              {listaOrdenada.slice(0,500).map((c,i)=>{
                const pends=getPendencias(c);
                const asaasGeral=c.asaas_status_sistema||c.asaas_status||'';
                const temVencido=c.asaas_status_impl==='OVERDUE'||c.asaas_status_equip==='OVERDUE'||c.asaas_status_sistema==='OVERDUE';
                const rowBg=temVencido?'#fff8f8':i%2===0?'#fff':'#fdfdfd';
                return(
                  <tr key={c.id} style={{borderTop:'1px solid '+C.border,background:rowBg}}>
                    {/* Empresa */}
                    <td style={{padding:'7px 10px',fontSize:11,fontWeight:700,color:C.text,maxWidth:160,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>
                      {temVencido&&<span style={{color:'#e74c3c',marginRight:4}}>⚠</span>}
                      {c.nome}
                    </td>
                    {/* CNPJ */}
                    <td style={{padding:'7px 10px',fontSize:10,color:C.textMuted,whiteSpace:'nowrap'}}>{c.cnpj||'—'}</td>
                    {/* Contato */}
                    <td style={{padding:'7px 10px',fontSize:10,color:C.textMuted,whiteSpace:'nowrap'}}>
                      <div style={{fontWeight:600,color:C.text,fontSize:11}}>{c.contato||'—'}</div>
                      <div style={{fontSize:9,color:C.textMuted}}>{c.fone||c.tel||''}</div>
                    </td>
                    {/* Vendedor */}
                    <td style={{padding:'7px 10px',fontSize:11,color:C.textMuted,whiteSpace:'nowrap'}}>{c.vendedor&&c.vendedor!=='—'?c.vendedor:'—'}</td>
                    {/* Plano */}
                    <td style={{padding:'7px 10px'}}>
                      <span style={{background:c.plano==='Ultimate'?'#ebf5fb':c.plano==='Pro'?'#e8f8f5':'#fef9f0',color:c.plano==='Ultimate'?C.blue:c.plano==='Pro'?C.teal:C.orange,padding:'1px 7px',borderRadius:8,fontSize:10,fontWeight:700}}>{c.plano||'—'}</span>
                    </td>
                    {/* Status CRM */}
                    <td style={{padding:'7px 10px'}}>
                      <span style={{background:corStatus(c.status)+'22',color:corStatus(c.status),padding:'1px 7px',borderRadius:8,fontSize:10,fontWeight:700,whiteSpace:'nowrap'}}>{labelStatus(c.status)}</span>
                    </td>
                    {/* Asaas */}
                    <td style={{padding:'7px 10px'}}>
                      {c.asaas_id?(
                        <div style={{display:'flex',flexDirection:'column',gap:2}}>
                          {parseFloat(c.vI)>0&&<div style={{display:'flex',gap:4,alignItems:'center'}}><span style={{fontSize:9,color:'#b45309',fontWeight:700,minWidth:22}}>Impl</span>{badgeAsaas(c.asaas_status_impl||'SEM_FATURAMENTO')}</div>}
                          {parseFloat(c.vE)>0&&<div style={{display:'flex',gap:4,alignItems:'center'}}><span style={{fontSize:9,color:'#276749',fontWeight:700,minWidth:22}}>Eq.</span>{badgeAsaas(c.asaas_status_equip||'SEM_FATURAMENTO')}</div>}
                          {parseFloat(c.vS)>0&&<div style={{display:'flex',gap:4,alignItems:'center'}}><span style={{fontSize:9,color:'#2b6cb0',fontWeight:700,minWidth:22}}>Sist</span>{badgeAsaas(c.asaas_status_sistema||asaasGeral||'SEM_FATURAMENTO')}</div>}
                        </div>
                      ):(
                        <span style={{fontSize:10,color:'#95a5a6'}}>🔵 Sem Asaas</span>
                      )}
                    </td>
                    {/* O que falta (só aba pendentes) */}
                    {abaRel==='pendentes'&&(
                      <td style={{padding:'7px 10px',minWidth:200}}>
                        <div style={{display:'flex',flexDirection:'column',gap:3}}>
                          {pends.map((p,pi)=>(
                            <div key={pi} style={{display:'flex',alignItems:'center',gap:5,flexWrap:'wrap'}}>
                              <span style={{fontSize:10,fontWeight:700,color:p.tipo==='impl'?'#b45309':p.tipo==='equip'?'#276749':'#2b6cb0',minWidth:70}}>{p.label}</span>
                              <span style={{fontSize:10,fontWeight:700,color:C.blue}}>{moeda(p.valor)}</span>
                              {p.parcelas>1&&<span style={{fontSize:9,color:C.textMuted}}>{p.parcelas}x</span>}
                              <span style={{fontSize:9,color:'#7f8c8d',background:'#f0f0f0',borderRadius:4,padding:'0 4px'}}>{p.forma}</span>
                              {badgePendencia(p)}
                            </div>
                          ))}
                          {pends.length===0&&<span style={{fontSize:10,color:'#27ae60'}}>✅ OK</span>}
                        </div>
                      </td>
                    )}
                    {/* Valores */}
                    <td style={{padding:'7px 10px',fontSize:11,fontWeight:700,color:parseFloat(c.vI)>0?C.orange:'#dde1e7',textAlign:'right',whiteSpace:'nowrap'}}>{parseFloat(c.vI)>0?moeda(c.vI):'—'}</td>
                    <td style={{padding:'7px 10px',fontSize:11,fontWeight:700,color:parseFloat(c.vE)>0?C.teal:'#dde1e7',textAlign:'right',whiteSpace:'nowrap'}}>{parseFloat(c.vE)>0?moeda(c.vE):'—'}</td>
                    <td style={{padding:'7px 10px',fontSize:11,fontWeight:700,color:parseFloat(c.vS)>0?C.purple:'#dde1e7',textAlign:'right',whiteSpace:'nowrap'}}>{parseFloat(c.vS)>0?moeda(c.vS):'—'}</td>
                    <td style={{padding:'7px 10px',fontSize:12,fontWeight:700,color:C.blue,textAlign:'right',whiteSpace:'nowrap'}}>{moeda(c.total)}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          {listaOrdenada.length>500&&<div style={{padding:'10px',textAlign:'center',fontSize:11,color:C.textMuted}}>Mostrando 500 de {listaOrdenada.length}. Use os filtros ou exporte para ver todos.</div>}
        </div>
        {/* Rodapé de totais */}
        {listaOrdenada.length>0&&(
          <div style={{background:'#f8f9fa',borderTop:'2px solid '+C.border,padding:'10px 14px',display:'flex',gap:20,flexWrap:'wrap',alignItems:'center'}}>
            <span style={{fontSize:11,fontWeight:700,color:C.text}}>{listaOrdenada.length} cliente(s)</span>
            <span style={{fontSize:11,color:C.orange}}>Impl: <strong>{moeda(listaOrdenada.reduce((s,c)=>s+(c.vI||0),0))}</strong></span>
            <span style={{fontSize:11,color:C.teal}}>Equip: <strong>{moeda(listaOrdenada.reduce((s,c)=>s+(c.vE||0),0))}</strong></span>
            <span style={{fontSize:11,color:C.purple}}>Sist/mês: <strong>{moeda(listaOrdenada.reduce((s,c)=>s+(c.vS||0),0))}</strong></span>
            <span style={{fontSize:12,fontWeight:700,color:C.blue}}>Total: <strong>{moeda(listaOrdenada.reduce((s,c)=>s+(c.total||0),0))}</strong></span>
          </div>
        )}
      </div>

      {/* ── IMPLANTAÇÕES POR ETAPA ── */}
      <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:14,marginBottom:14}}>
        <div style={{background:C.card,borderRadius:8,padding:'16px',boxShadow:'0 1px 3px rgba(0,0,0,.08)'}}>
          <div style={{fontWeight:700,fontSize:12,color:C.text,marginBottom:12,textTransform:'uppercase'}}>📊 Implantações por etapa</div>
          {porEtapa.length===0&&<div style={{color:C.textMuted,fontSize:12,textAlign:'center',padding:'16px 0'}}>Nenhuma implantação registrada.</div>}
          {porEtapa.map(e=>(
            <div key={e.id} style={{display:'flex',alignItems:'center',gap:10,marginBottom:8}}>
              <div style={{width:10,height:10,borderRadius:2,background:e.color,flexShrink:0}}/>
              <div style={{flex:1,fontSize:12,color:C.text,fontWeight:600}}>{e.label}</div>
              <div style={{height:8,borderRadius:4,background:'#ecf0f1',width:100,flexShrink:0}}>
                <div style={{height:'100%',borderRadius:4,background:e.color,width:Math.min(Math.round((e.qtd/Math.max(todos.length,1))*400),100)+'%'}}/>
              </div>
              <div style={{fontSize:12,fontWeight:700,color:C.text,width:28,textAlign:'right'}}>{e.qtd}</div>
            </div>
          ))}
        </div>
        <div style={{background:C.card,borderRadius:8,padding:'16px',boxShadow:'0 1px 3px rgba(0,0,0,.08)'}}>
          <div style={{fontWeight:700,fontSize:12,color:C.text,marginBottom:12,textTransform:'uppercase'}}>💾 Exportar relatórios</div>
          <div style={{display:'flex',flexDirection:'column',gap:8}}>
            <button onClick={()=>exportarExcel(pendentes,nomeArq()+'_pendentes')} style={{display:'flex',alignItems:'center',gap:6,padding:'9px 14px',borderRadius:6,border:'none',background:'#fff8ee',color:'#b45309',fontWeight:700,cursor:'pointer',fontSize:12,border:'1px solid #f5a623'}}>
              <i className="ti ti-file-spreadsheet"/> Exportar pendências ({pendentes.length})
            </button>
            <button onClick={()=>exportarExcel(dadosFiltrados,nomeArq()+'_clientes')} style={{display:'flex',alignItems:'center',gap:6,padding:'9px 14px',borderRadius:6,border:'none',background:C.green,color:'#fff',fontWeight:700,cursor:'pointer',fontSize:12}}>
              <i className="ti ti-file-spreadsheet"/> Exportar todos os clientes ({dadosFiltrados.length})
            </button>
            <button onClick={()=>{const rows=porEtapa.flatMap(e=>e.clientes.map(c=>({...c})));exportarExcel(rows,nomeArq()+'_implantacao');}} style={{display:'flex',alignItems:'center',gap:6,padding:'9px 14px',borderRadius:6,border:'none',background:C.purple,color:'#fff',fontWeight:700,cursor:'pointer',fontSize:12}}>
              <i className="ti ti-file-spreadsheet"/> Exportar implantações
            </button>
            <button onClick={()=>exportarExcel(inadimplentes,nomeArq()+'_inadimplentes')} style={{display:'flex',alignItems:'center',gap:6,padding:'9px 14px',borderRadius:6,border:'none',background:'#fff5f5',color:'#c0392b',fontWeight:700,cursor:'pointer',fontSize:12,border:'1px solid #e74c3c'}}>
              <i className="ti ti-file-spreadsheet"/> Exportar inadimplentes ({inadimplentes.length})
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

